const TrialExtensionRedeem = lazyWithRetry(() => import('./pages/TrialExtensionRedeem'), 'TrialExtensionRedeem');

// LandingPage é mantida estática para velocidade máxima de FCP/LCP na Home
import LandingPage from './pages/LandingPage';

import { CookieConsent } from './components/CookieConsent';
import { CustomModalContainer } from './components/common/CustomModalContainer';
import { appendBrandAssetVersion, getBrandAssetSignature, getBrandSocialShareUrl } from './utils/brandAssets';
import {
  canAccessApplication,
  completeOnboarding,
  getOnboardingDestination,
  hydrateOnboardingFromProfile,
  isOnboardingComplete,
} from './utils/onboarding';
import { InstallPrompt } from './components/common/InstallPrompt';
import { PermissionNotice } from './components/common/PermissionNotice';
import { canUseNativeGoogleOAuthCallback, clearPendingGoogleScopes, getCurrentGoogleOAuthRedirectUrl, readPendingGoogleScopes, requestGoogleOAuth } from './services/googleAuth';
import { isGoogleAccessTokenFresh } from './utils/googleAuthSession';
import { clearLazyRetryQueryParam, lazyWithRetry } from './utils/lazyWithRetry';
import { ChunkLoadErrorBoundary } from './components/common/ChunkLoadErrorBoundary';
import { addNativeBillingListener, hasNativeBillingBridge, verifyGooglePlaySubscription } from './services/billing';
import { captureAcquisitionData, captureNativeInstallAttribution, syncAcquisitionWithDatabase, getCurrentAcquisitionData } from './utils/acquisitionTracking';
import { calculateAcquisitionChannel, getAcquisitionDistribution, getAcquisitionPlatform } from './utils/acquisitionAttribution';
import { isPublicAcquisitionPathname, sendAcquisitionTelemetry } from './services/acquisitionTelemetry';
import { PushPermissionPrompt } from './components/notifications/PushPermissionPrompt';
import { EnvironmentBanner } from './components/layout/EnvironmentBanner';
import { getAnalyticsConsent, getCheckoutAttributionWithRetry, getConsentPreferences, refreshMarketingAnalyticsForCurrentRoute, sanitizeCurrentMarketingUrl, setAnalyticsUser, syncAnalyticsConsentForCurrentUser, trackConfirmedMetaRegistrationOnce, trackEvent, trackPageView, trackSignUpOnce } from './services/analytics';

const GOOGLE_SILENT_REFRESH_KEY = 'evolucao-clinica:google-silent-refresh';

function NativeBillingRestore() {
  const user = useAuthStore((state) => state.user);
  const restoredUserRef = useRef<string | null>(null);
  const lastRestoreAtRef = useRef(0);

  useEffect(() => {
    if (!user || !hasNativeBillingBridge()) return;
    const removeListener = addNativeBillingListener((event) => {
      if (
          !['play_purchase', 'play_purchase_pending'].includes(event.type) ||
        event.restored !== true ||
        !event.productId ||
        !event.purchaseToken
      ) return;
      const planId = event.productId === 'evolucao_yearly' ? 'yearly' : 'monthly';
      void getCheckoutAttributionWithRetry(undefined, 5)
        .then((attribution) => verifyGooglePlaySubscription({
          planId,
          productId: event.productId,
          purchaseToken: event.purchaseToken,
          attribution
        }))
        .catch((error) => {
          console.error('[BillingRestore] Falha ao restaurar compra Google Play:', error);
        });
    });

      if (restoredUserRef.current !== user.id) {
      restoredUserRef.current = user.id;
      try {
        window.NativeBillingBridge?.restorePurchases(user.id);
      } catch (error) {
        console.error('[BillingRestore] Não foi possível consultar compras:', error);
      }
      }
      const reconcileOnForeground = () => {
        if (document.visibilityState !== 'visible' || Date.now() - lastRestoreAtRef.current < 2_000) return;
        lastRestoreAtRef.current = Date.now();
        try { window.NativeBillingBridge?.restorePurchases(user.id); } catch { /* next foreground retries */ }
      };
      document.addEventListener('visibilitychange', reconcileOnForeground);
      window.addEventListener('pageshow', reconcileOnForeground);
      window.addEventListener('focus', reconcileOnForeground);
      return () => {
        removeListener();
        document.removeEventListener('visibilitychange', reconcileOnForeground);
        window.removeEventListener('pageshow', reconcileOnForeground);
        window.removeEventListener('focus', reconcileOnForeground);
      };
  }, [user]);

  return null;
}

function AnalyticsRouteObserver() {
  const location = useLocation();
  const lastPageRef = useRef<string | null>(null);

  useEffect(() => {
    const sendPageView = () => {
      captureAcquisitionData();
      if (isPublicAcquisitionPathname(location.pathname)) {
        const acquisition = getCurrentAcquisitionData();
        sendAcquisitionTelemetry('acquisition_arrival', {
          pathname: location.pathname,
          channel: calculateAcquisitionChannel(acquisition),
          campaignPresent: Boolean(acquisition.utm_campaign),
          platform: getAcquisitionPlatform(acquisition),
          distribution: getAcquisitionDistribution(acquisition),
          dedupeKey: `acquisition_arrival:${location.pathname}`
        });
      }
      sanitizeCurrentMarketingUrl();
      refreshMarketingAnalyticsForCurrentRoute();
      if (getAnalyticsConsent() !== 'granted') {
        lastPageRef.current = null;
        return;
      }
      const pageKey = `${location.pathname}`;
      if (lastPageRef.current === pageKey) return;
      lastPageRef.current = pageKey;
      trackPageView(location.pathname);
    };

    sendPageView();
    window.addEventListener('analytics-consent-changed', sendPageView);
    return () => window.removeEventListener('analytics-consent-changed', sendPageView);
  }, [location.hash, location.pathname, location.search]);

  return null;
}

function ProtectedRoute({ children }: { children: React.ReactNode }) {
  const { user, isAuthReady, profileStatus, profileRole, subscriptionStatus, subscriptionEndsAt } = useAuthStore();
  const location = useLocation();
  const isOnboardingRoute = location.pathname.startsWith('/onboarding') || location.pathname.startsWith('/checkout');

  if (!isAuthReady) {
    return <SplashScreen message="Preparando seu ambiente clínico..." />;
  }

  if (!user) {
    return <Navigate to="/login" replace />;
  }

  if (profileStatus === null || profileRole === null) {
    return <SplashScreen message="Carregando seus dados..." />;
  }

  if (profileStatus === 'pending') {
    return <Navigate to="/pending" replace />;
  }

  if (profileStatus === 'inactive') {
    return <Navigate to="/pending?status=inactive" replace />;
  }

  if (isOnboardingRoute) {
    return <>{children}</>;
  }

  // Se o fluxo pendente de checkout do plano da home estiver ativo
  const isPendingCheckoutFlow = typeof window !== 'undefined' && window.sessionStorage.getItem('pending_checkout_flow') === 'true';

  if (isPendingCheckoutFlow && profileRole !== 'admin') {
    const now = new Date();
    const endsAt = subscriptionEndsAt ? new Date(subscriptionEndsAt) : null;
    const isExpired = endsAt ? endsAt < now : false;
    const isActive = subscriptionStatus === 'active';

    if (!isActive || isExpired) {
      if (location.pathname !== '/checkout') {
        return <Navigate to="/checkout" replace />;
      }
      return <>{children}</>;
    } else {
      // Plano ficou ativo! Limpamos a flag e deixamos seguir para o onboarding
      window.sessionStorage.removeItem('pending_checkout_flow');
    }
  }

  if (
    profileRole !== 'admin'
    && user
    && !isOnboardingComplete(user.id)
    && !canAccessApplication(user.id)
  ) {
    const destination = getOnboardingDestination(user.id);
    const cleanDestPath = destination.split('?')[0];
    const isEditingPatientOnboarding = location.pathname.match(/^\/painel\/patients\/[^/]+\/edit$/) && location.search.includes('onboarding=1');

    if (location.pathname !== cleanDestPath && !isEditingPatientOnboarding) {
      return <Navigate to={destination} replace />;
    }
  }

  // Mantém acessíveis as páginas de conta e recursos premium mesmo sem plano ativo,
  // para que o usuário possa gerenciar a conta ou contratar novamente.
  if (
    location.pathname === '/painel/subscription' ||
    location.pathname === '/painel/profile' ||
    location.pathname === '/painel/logotipo-personalizado' ||
    location.pathname === '/painel/backup-exportacao'
  ) {
    return <>{children}</>;
  }

  // Se não for admin, verifica se o usuário possui plano ativo e não expirado
  if (profileRole !== 'admin') {
    const now = new Date();
    const endsAt = subscriptionEndsAt ? new Date(subscriptionEndsAt) : null;
    const isExpired = endsAt ? endsAt < now : false;
    const isActive = subscriptionStatus === 'active' || subscriptionStatus === 'trialing';

    if (!isActive || isExpired) {
      return <Navigate to="/painel/subscription" replace />;
    }
  }

  return <>{children}</>;
}

function AdminRoute({ children }: { children: React.ReactNode }) {
  const { user, isAuthReady, profileRole } = useAuthStore();

  if (!isAuthReady) {
    return <SplashScreen message="Carregando área administrativa..." />;
  }

  if (user && profileRole === null) {
    return <SplashScreen message="Carregando permissões administrativas..." />;
  }

  if (user && profileRole !== 'admin' && profileRole !== 'therapist') {
    return <Navigate to="/" replace />;
  }

  return <>{children}</>;
}

function RootRoute() {
  const { isAuthReady, user, profileRole } = useAuthStore();

  if (!isAuthReady) {
    return <SplashScreen message="Iniciando Evolução Clínica..." />;
  }

  if (user) {
    if (
      profileRole !== 'admin'
      && !isOnboardingComplete(user.id)
      && !canAccessApplication(user.id)
    ) {
      return <Navigate to={getOnboardingDestination(user.id)} replace />;
    }

    const oauthRedirectPath = localStorage.getItem('oauth_redirect_path');
    if (oauthRedirectPath) {
      localStorage.removeItem('oauth_redirect_path');
      return <Navigate to={oauthRedirectPath} replace />;
    }

    return <Navigate to="/painel/dashboard" replace />;
  }

  return <LandingPage />;
}


export default function App() {
  const {
    setUser,
    setAuthReady,
    setProfileInfo,
    setGoogleAccessToken,
    setGoogleAccessUserId,
    setGoogleAccessTokenIssuedAt,
    setGoogleGrantedScopes
  } = useAuthStore();
  const professionalChannelRef = useRef<any>(null);
  const siteConfig = useSiteConfig();
  const assetSignature = getBrandAssetSignature(siteConfig);

  useEffect(() => {
    clearLazyRetryQueryParam();
    captureAcquisitionData();
    const captureAllowedNativeAttribution = () => {
      if (getConsentPreferences()?.marketing === true) void captureNativeInstallAttribution();
    };
    captureAllowedNativeAttribution();
    window.addEventListener('cookie-consent-accepted', captureAllowedNativeAttribution);
    const cleanupMarketingUrlTimer = window.setTimeout(() => {
      const pathname = window.location.pathname;
      const isAcquisitionPage = pathname === '/' || pathname === '/jornada' || pathname === '/jornada-15-dias' || pathname.startsWith('/jornada/');
      if (isAcquisitionPage && sanitizeCurrentMarketingUrl()) refreshMarketingAnalyticsForCurrentRoute();
    }, 0);
    return () => {
      window.clearTimeout(cleanupMarketingUrlTimer);
      window.removeEventListener('cookie-consent-accepted', captureAllowedNativeAttribution);
    };
  }, []);

  useEffect(() => {
    const updateLink = (selector: string, rel: string, href: string, type?: string, sizes?: string) => {
      let link = document.querySelector<HTMLLinkElement>(selector);
      if (!link) {
        link = document.createElement('link');
        link.setAttribute('rel', rel);
        document.head.appendChild(link);
      }
      link.rel = rel;
      if (type) link.type = type;
      if (sizes) link.setAttribute('sizes', sizes);
      link.href = href;
    };

    const updateMeta = (selector: string, attr: 'name' | 'property', value: string, content: string) => {
      let meta = document.querySelector<HTMLMetaElement>(selector);
      if (!meta) {
        meta = document.createElement('meta');
        meta.setAttribute(attr, value);
        document.head.appendChild(meta);
      }
      meta.setAttribute(attr, value);
      meta.content = content;
    };

    const faviconUrl = appendBrandAssetVersion('/api/favicon', assetSignature);
    const appleTouchIconUrl = appendBrandAssetVersion('/api/apple-touch-icon', assetSignature);
    const socialImageUrl = appendBrandAssetVersion(getBrandSocialShareUrl(siteConfig), assetSignature);

    updateLink("link[rel='icon']", 'icon', faviconUrl, undefined, '32x32');
    updateLink("link[rel='shortcut icon']", 'shortcut icon', faviconUrl);
    updateLink("link[rel='apple-touch-icon']", 'apple-touch-icon', appleTouchIconUrl, 'image/png');
    updateLink("link[rel='manifest']", 'manifest', appendBrandAssetVersion('/manifest.webmanifest', assetSignature), 'application/manifest+json');
    updateMeta("meta[name='theme-color']", 'name', 'theme-color', siteConfig.pwa_theme_color);
    updateMeta("meta[property='og:image']", 'property', 'og:image', socialImageUrl);
    updateMeta("meta[name='twitter:image']", 'name', 'twitter:image', socialImageUrl);
    const seoTitle = siteConfig.seo_title || siteConfig.pwa_app_name;
    const seoDescription = siteConfig.seo_description || siteConfig.pwa_description;
    document.title = seoTitle;
    updateMeta("meta[name='description']", 'name', 'description', seoDescription);
    updateMeta("meta[property='og:title']", 'property', 'og:title', seoTitle);
    updateMeta("meta[property='og:description']", 'property', 'og:description', seoDescription);
    updateMeta("meta[name='twitter:title']", 'name', 'twitter:title', seoTitle);
    updateMeta("meta[name='twitter:description']", 'name', 'twitter:description', seoDescription);
  }, [siteConfig, assetSignature]);
  const pendingOnboardingNoticeRef = useRef<string | null>(null);
  const authSessionHandlingRef = useRef(false);
  const metaRegistrationTrackingRef = useRef<{ userId: string; promise: Promise<boolean> } | null>(null);

  const clearSilentGoogleRefreshFlag = (userId?: string | null) => {
    if (typeof window === 'undefined' || !userId) return;
    const current = sessionStorage.getItem(GOOGLE_SILENT_REFRESH_KEY);
    if (current === userId) {
      sessionStorage.removeItem(GOOGLE_SILENT_REFRESH_KEY);
    }
  };

  const markSilentGoogleRefreshFlag = (userId?: string | null) => {
    if (typeof window === 'undefined' || !userId) return;
    sessionStorage.setItem(GOOGLE_SILENT_REFRESH_KEY, userId);
  };

  const hasSilentGoogleRefreshFlag = (userId?: string | null) => {
    if (typeof window === 'undefined' || !userId) return false;
    return sessionStorage.getItem(GOOGLE_SILENT_REFRESH_KEY) === userId;
  };

  const clearInvalidProfessionalSession = async () => {
    await clearProfessionalChannel();
    pendingOnboardingNoticeRef.current = null;
    setGoogleAccessToken(null);
    setGoogleAccessUserId(null);
    setGoogleAccessTokenIssuedAt(null);
    setGoogleGrantedScopes([]);
    clearSilentGoogleRefreshFlag(useAuthStore.getState().googleAccessUserId);
    setUser(null);
    setProfileInfo(null, null, null, null, null, null);
    setAnalyticsUser(null);
    clearPendingGoogleScopes();
    await supabase.auth.signOut();
  };

  const clearProfessionalChannel = async () => {
    if (professionalChannelRef.current) {
      const channel = professionalChannelRef.current;
      professionalChannelRef.current = null;
      await supabase.removeChannel(channel);
    }
  };

  useEffect(() => {
    const trackMetaRegistrationBeforeAppAccess = (session: any) => {
      const existing = metaRegistrationTrackingRef.current;
      if (existing?.userId === session.user.id) return existing.promise;

      const promise = (async () => {
        if (sanitizeCurrentMarketingUrl()) refreshMarketingAnalyticsForCurrentRoute();
        // This sync remains useful for all server-side analytics, but its result
        // no longer gates registration: the pending endpoint persists the same
        // preferences atomically before reading the marker.
        await syncAnalyticsConsentForCurrentUser(session.user.id);
        return trackConfirmedMetaRegistrationOnce(session.access_token);
      })();

      metaRegistrationTrackingRef.current = { userId: session.user.id, promise };
      void promise.finally(() => {
        if (metaRegistrationTrackingRef.current?.promise === promise) {
          metaRegistrationTrackingRef.current = null;
        }
      });
      return promise;
    };

    const bootstrapProfessionalAccess = async (session: any) => {
      const response = await fetch('/api/onboarding/bootstrap', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${session.access_token}`
        }
      });

      const data = await response.json().catch(() => ({}));
      if (!response.ok) {
        throw new Error(data.error || 'Falha ao sincronizar acesso do profissional.');
      }

      return data;
    };

    const handleAuthSession = async (session: any) => {
      if (authSessionHandlingRef.current) {
        return;
      }

      authSessionHandlingRef.current = true;

      const currentState = useAuthStore.getState();

      try {
        if (session) {
          const pendingScopes = readPendingGoogleScopes();

          if (currentState.googleAccessUserId && currentState.googleAccessUserId !== session.user.id) {
            setGoogleAccessToken(null);
            setGoogleAccessUserId(null);
            setGoogleAccessTokenIssuedAt(null);
            setGoogleGrantedScopes([]);
            clearSilentGoogleRefreshFlag(currentState.googleAccessUserId);
          }

          if (pendingScopes.length > 0) {
            const mergedScopes = Array.from(new Set([
              ...currentState.googleGrantedScopes,
              ...pendingScopes
            ]));
            setGoogleGrantedScopes(mergedScopes);
            setGoogleAccessUserId(session.user.id);
            clearPendingGoogleScopes();
          }

          const latestState = useAuthStore.getState();

          const sameGoogleUser = latestState.googleAccessUserId === session.user.id;
          const hasPersistedGoogleScopes = latestState.googleGrantedScopes.length > 0;
          const hasNewProviderToken = Boolean(
            session.provider_token && session.provider_token !== latestState.googleAccessToken
          );
          const shouldSilentlyRefreshGoogle =
            sameGoogleUser &&
            hasPersistedGoogleScopes &&
            canUseNativeGoogleOAuthCallback() &&
            !hasNewProviderToken &&
            !isGoogleAccessTokenFresh(
              latestState.googleAccessToken,
              latestState.googleAccessTokenIssuedAt
            ) &&
            !hasSilentGoogleRefreshFlag(session.user.id);

          if (shouldSilentlyRefreshGoogle) {
            markSilentGoogleRefreshFlag(session.user.id);
            const { error } = await requestGoogleOAuth({
              requiredScopes: latestState.googleGrantedScopes,
              currentGrantedScopes: latestState.googleGrantedScopes,
              redirectTo: getCurrentGoogleOAuthRedirectUrl(),
              prompt: 'none',
              loginHint: session.user.email || undefined
            });

            if (error) {
              console.warn('Falha ao renovar silenciosamente o token do Google:', error);
              clearSilentGoogleRefreshFlag(session.user.id);
            } else {
              return;
            }
          }

          const isSameUser = currentState.user?.id === session.user.id;
          const hasProfile = currentState.profileStatus !== null;

          if (isSameUser && hasProfile) {
            // Se o provider_token do Google mudou ou foi fornecido, atualiza
            if (session.provider_token) {
              if (currentState.googleAccessToken !== session.provider_token) {
                setGoogleAccessToken(session.provider_token);
                setGoogleAccessUserId(session.user.id);
              }
              clearSilentGoogleRefreshFlag(session.user.id);
            }
            setAuthReady(true);
            return;
          }

          await clearProfessionalChannel();

          setUser(session.user);
          if (session.provider_token) {
            setGoogleAccessToken(session.provider_token);
            setGoogleAccessUserId(session.user.id);
            clearSilentGoogleRefreshFlag(session.user.id);
          } else {
            // Opcional: em alguns fluxos do Supabase o token do provedor pode ser guardado no localStorage
            // se o redirecionamento limpar o provider_token após a primeira captura.
          }

          let profileData: any = null;

          try {
            const { data, error } = await supabase
              .from('professionals')
              .select('*')
              .eq('id', session.user.id)
              .single();

            if (error) {
              console.error("Erro ao buscar profissional no Supabase:", error);
              // Se for PGRST116 (registro não encontrado/novo cadastro), aguarda liberação
              if (error.code === 'PGRST116') {
                const bootstrapData = await bootstrapProfessionalAccess(session);
                profileData = bootstrapData.profile || null;

                if (!profileData) {
                  throw new Error('Não foi possível carregar o perfil do profissional.');
                }
              } else {
                throw error;
              }
            } else {
              profileData = data;
            }

            if (!profileData) {
              throw new Error('Perfil do profissional indisponível.');
            }

            if (profileData.status === 'pending') {
              try {
                const bootstrapData = await bootstrapProfessionalAccess(session);
                profileData = bootstrapData.profile || profileData;
              } catch (bootstrapError) {
                console.error('Erro ao sincronizar onboarding pendente:', bootstrapError);
              }
            }

            setProfileInfo(
              profileData.status,
              profileData.role || 'therapist',
              profileData.subscription_plan,
              profileData.subscription_status,
              profileData.subscription_ends_at,
              profileData.trial_ends_at
            );
            setAnalyticsUser(session.user.id, {
              professional_segment: typeof profileData.professional_title === 'string' ? profileData.professional_title : null,
              work_context: typeof profileData.work_context === 'string' ? profileData.work_context : null,
              subscription_plan: typeof profileData.subscription_plan === 'string' ? profileData.subscription_plan : null,
              app_environment: typeof navigator !== 'undefined' && /EvolucaoClinicaApp/i.test(navigator.userAgent) ? 'android' : 'web'
            });
            void syncAnalyticsConsentForCurrentUser();

            const nativeAttribution = getConsentPreferences()?.marketing === true
              ? captureNativeInstallAttribution()
              : Promise.resolve(null);
            void nativeAttribution.finally(() => syncAcquisitionWithDatabase(session.user.id, profileData.acquisition_info));

            pendingOnboardingNoticeRef.current = profileData.status === 'pending' ? session.user.id : null;

            hydrateOnboardingFromProfile(session.user.id, profileData);

            // Sincronização do status do onboarding
            const localComplete = isOnboardingComplete(session.user.id);
            const dbComplete = profileData.onboarding_completed === true;

            if (dbComplete && !localComplete) {
              completeOnboarding(session.user.id);
            } else if (localComplete && !dbComplete) {
              await supabase
                .from('professionals')
                .update({ onboarding_completed: true })
                .eq('id', session.user.id);
            }
          } catch (profileError) {
            console.error('Erro ao processar perfil do profissional:', profileError);
            const isMissingProfile = profileError instanceof Error && (
              profileError.message.includes('Perfil do profissional indisponível.') ||
              profileError.message.includes('Não foi possível carregar o perfil do profissional.')
            );

            if (isMissingProfile || currentState.profileStatus === null || currentState.profileRole === null) {
              await clearInvalidProfessionalSession();
              return;
            }
          }

          try {
            const channel = supabase
              .channel(`professional-status-${session.user.id}`)
              .on(
                'postgres_changes',
                {
                  event: '*',
                  schema: 'public',
                  table: 'professionals',
                  filter: `id=eq.${session.user.id}`
                },
                async () => {
                  try {
                    const { data: updatedProf } = await supabase
                      .from('professionals')
                      .select('*')
                      .eq('id', session.user.id)
                      .single();

                    if (updatedProf) {
                      if (updatedProf.force_google_disconnect) {
                        setGoogleAccessToken(null);
                        localStorage.setItem('force_google_prompt', 'true');
                        await supabase
                          .from('professionals')
                          .update({ force_google_disconnect: false })
                          .eq('id', session.user.id);
                        await supabase.auth.signOut();
                        return;
                      }

                      setProfileInfo(
                        updatedProf.status,
                        updatedProf.role || 'therapist',
                        updatedProf.subscription_plan,
                        updatedProf.subscription_status,
                        updatedProf.subscription_ends_at,
                        updatedProf.trial_ends_at
                      );
                      if (updatedProf.status !== 'pending') {
                        pendingOnboardingNoticeRef.current = null;
                      }

                      hydrateOnboardingFromProfile(session.user.id, updatedProf);

                      // Sincronização do status do onboarding em tempo real
                      const localComplete = isOnboardingComplete(session.user.id);
                      const dbComplete = updatedProf.onboarding_completed === true;

                      if (dbComplete && !localComplete) {
                        completeOnboarding(session.user.id);
                      } else if (localComplete && !dbComplete) {
                        await supabase
                          .from('professionals')
                          .update({ onboarding_completed: true })
                          .eq('id', session.user.id);
                      }
                    } else {
                      await clearInvalidProfessionalSession();
                    }
                  } catch (profileError) {
                    console.error('Erro ao sincronizar status do profissional:', profileError);
                    await clearInvalidProfessionalSession();
                  }
                }
              )
              .subscribe();

            professionalChannelRef.current = channel;
          } catch (channelError) {
            console.error('Erro ao configurar canal realtime do profissional:', channelError);
          }
        } else {
          await clearProfessionalChannel();
          setAnalyticsUser(null);
          pendingOnboardingNoticeRef.current = null;
          clearSilentGoogleRefreshFlag(currentState.googleAccessUserId);
          if (currentState.user !== null || currentState.profileStatus !== null) {
            setUser(null);
            setProfileInfo(null, null, null, null, null, null);
          }
        }
      } finally {
        authSessionHandlingRef.current = false;
        setAuthReady(true);
      }
    };

    // Aguarda a restauração real da sessão antes de permitir que as rotas decidam
    // se devem mostrar o login. Em alguns WebViews a leitura do armazenamento
    // persistido demora mais do que uma abertura comum; tratar essa espera como
    // sessão nula fazia o app piscar a tela de login e entrar logo em seguida.
    const loadInitialSession = async () => {
      try {
        const result = await supabase.auth.getSession();
        if (result.data.session) {
          await trackMetaRegistrationBeforeAppAccess(result.data.session);
        }
        await handleAuthSession(result.data.session);
      } catch (error) {
        console.error('[Auth] Falha ao recuperar a sessão inicial:', error);
        await handleAuthSession(null);
      }
    };

    void loadInitialSession();

    // Escuta mudanças no Auth
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      // O callback do Auth retorna imediatamente; consultas adicionais são
      // executadas fora do lock interno do cliente Supabase.
      window.setTimeout(() => {
        void (async () => {
          if (session && _event === 'SIGNED_IN') {
            const method = typeof session.user.app_metadata?.provider === 'string'
              ? session.user.app_metadata.provider
              : 'google';
            trackEvent('login', { method }, { dedupeKey: `login:${session.user.id}:${session.user.last_sign_in_at || 'session'}` });
            // Compatibilidade exclusiva com o evento legado de Analytics. A Meta
            // não usa esta heurística: CompleteRegistration depende do marcador
            // transacional criado pelo trigger de auth.users.
            const createdAt = new Date(session.user.created_at).getTime();
            const signedInAt = new Date(session.user.last_sign_in_at || '').getTime();
            if (Number.isFinite(createdAt) && Number.isFinite(signedInAt) && Math.abs(signedInAt - createdAt) < 5 * 60 * 1000) {
              trackSignUpOnce(session.user.id, method);
            }
          }
          // Supabase emits INITIAL_SESSION independently of getSession(). Both
          // paths must await the same promise before handleAuthSession can expose
          // the user and let /login redirect to the blocked /onboarding route.
          if (session && (_event === 'SIGNED_IN' || _event === 'INITIAL_SESSION')) {
            await trackMetaRegistrationBeforeAppAccess(session);
          }
          await handleAuthSession(session);
        })();
      }, 0);
    });

    return () => {
      clearProfessionalChannel();
      subscription.unsubscribe();
    };
  }, [setUser, setAuthReady, setProfileInfo, setGoogleAccessToken, setGoogleAccessUserId, setGoogleAccessTokenIssuedAt, setGoogleGrantedScopes]);

  return (
    <Router>
      <EnvironmentBanner />
      <AnalyticsRouteObserver />
      <CookieConsent />
      <InstallPrompt />
      <PermissionNotice />
      <CustomModalContainer />
      <NativeBillingRestore />
      <PushPermissionPrompt />
      <SpeedInsights />

      <ChunkLoadErrorBoundary>
        <Suspense fallback={<SplashScreen message="Carregando..." />}>
          <Routes>
          <Route path="/login" element={<Login />} />
          <Route path="/checkout" element={<ProtectedRoute><CheckoutPage /></ProtectedRoute>} />
          <Route path="/checkout/success" element={<ProtectedRoute><SuccessPage /></ProtectedRoute>} />
          <Route path="/checkout/sucess" element={<ProtectedRoute><SuccessPage /></ProtectedRoute>} />
          <Route path="/onboarding" element={<ProtectedRoute><Onboarding /></ProtectedRoute>} />
          <Route path="/pending" element={<PendingApproval />} />
          <Route path="/privacy" element={<PrivacyPolicy />} />
          <Route path="/terms" element={<TermsOfService />} />
          <Route path="/delete-account" element={<DeleteAccount />} />
          <Route path="/preferencias-de-comunicacao" element={<Navigate to="/painel/preferencias-de-comunicacao" replace />} />
          <Route path="/descadastro" element={<Unsubscribe />} />
          <Route path="/feedback/continuidade" element={<ContinuityFeedback />} />
          <Route path="/reativar-teste" element={<TrialExtensionRedeem />} />
          <Route path="/public/reports/:reportId" element={<PublicReportView />} />
          <Route path="/jornada" element={<PublicJourneyIndex />} />
          <Route path="/jornada/:journeySlug" element={<PublicJourneyIndex />} />
          <Route path="/jornada/:journeySlug/:contentSlug" element={<PublicJourneyIndex />} />
          <Route path="/jornada-15-dias" element={<PublicJourneyIndex />} />

          {/* Admin Panel Routes */}
          <Route path="/admin/*" element={<AdminRoute><AdminPanel /></AdminRoute>} />

          {/* Client/Therapist Panel Routes */}
          <Route path="/painel" element={<ProtectedRoute><Layout /></ProtectedRoute>}>
            <Route index element={<Navigate to="dashboard" replace />} />
            <Route path="dashboard" element={<Dashboard />} />
            <Route path="patients" element={<Patients />} />
            <Route path="patients/new" element={<PatientForm />} />
            <Route path="patients/:id/edit" element={<PatientForm />} />
            <Route path="patients/:id" element={<PatientDetail />} />
            <Route path="patients/:id/anamnesis" element={<PatientAnamnesis />} />
            <Route path="patients/:id/sessions" element={<PatientSessions />} />
            <Route path="patients/:id/evolutions/new" element={<NewEvolution />} />
            <Route path="history" element={<History />} />
            <Route path="tutorial" element={<Tutorial />} />
            <Route path="share-target" element={<ShareTarget />} />
            <Route path="subscription" element={<Subscription />} />
            <Route path="migration" element={<Migration />} />
            <Route path="profile" element={<Profile />} />
            <Route path="logotipo-personalizado" element={<CustomLogo />} />
            <Route path="backup-exportacao" element={<BackupExport />} />
            <Route path="about" element={<AboutApp />} />
            <Route path="notifications" element={<Notifications />} />
            <Route path="preferencias-de-comunicacao" element={<CommunicationPreferences />} />
            <Route path="support" element={<SupportTickets />} />
            <Route path="support/:ticketId" element={<SupportTicketDetail />} />
            <Route path="sugestoes" element={<Feedback />} />
          </Route>

          {/* Redirects */}
          <Route path="/" element={<RootRoute />} />
          <Route path="/patients" element={<Navigate to="/painel/patients" replace />} />
          <Route path="/share-target" element={<Navigate to="/painel/share-target" replace />} />
          <Route path="/api/share-target" element={<Navigate to="/painel/share-target" replace />} />
          <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </Suspense>
      </ChunkLoadErrorBoundary>
    </Router>
  );
}

