import React, { useEffect, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { Check, Cookie, ExternalLink, Shield } from 'lucide-react';
import { getConsentPreferences, setConsentPreferences } from '../services/analytics';
import { sendAcquisitionTelemetry } from '../services/acquisitionTelemetry';

const PUBLIC_PRIVACY_WIDGET_EXACT_PATHS = new Set([
  '/',
  '/login',
  '/privacy',
  '/terms',
  '/delete-account',
  '/descadastro',
  '/feedback/continuidade',
  '/reativar-teste',
  '/jornada-15-dias'
]);

export const isPublicPrivacyWidgetPath = (pathname: string) => (
  PUBLIC_PRIVACY_WIDGET_EXACT_PATHS.has(pathname)
  || pathname === '/jornada'
  || pathname.startsWith('/jornada/')
);

export const CookieConsent = () => {
  const location = useLocation();
  const [ready, setReady] = useState(false);
  const [visible, setVisible] = useState(false);
  const [preferencesOpen, setPreferencesOpen] = useState(false);
  const [analytics, setAnalytics] = useState(false);
  const [marketing, setMarketing] = useState(false);

  const load = () => {
    const current = getConsentPreferences();
    setAnalytics(current?.analytics ?? false);
    setMarketing(current?.marketing ?? false);
    setVisible(current === null);
    if (current === null) sendAcquisitionTelemetry('consent_banner_shown', { dedupeKey: 'consent_banner_shown' });
    setReady(true);
    return current;
  };

  useEffect(() => {
    const openPreferences = () => {
      load();
      setPreferencesOpen(true);
      setVisible(true);
    };

    load();
    window.addEventListener('cookie-consent-open', openPreferences);
    return () => window.removeEventListener('cookie-consent-open', openPreferences);
  }, []);

  const save = (nextAnalytics = analytics, nextMarketing = marketing) => {
    setConsentPreferences({ analytics: nextAnalytics, marketing: nextMarketing });
    setVisible(false);
    setPreferencesOpen(false);
    window.dispatchEvent(new Event('cookie-consent-accepted'));
  };

  const closePreferences = () => {
    const hasRecordedChoice = getConsentPreferences() !== null;
    setPreferencesOpen(false);
    setVisible(!hasRecordedChoice);
  };

  const item = (
    label: string,
    description: string,
    checked: boolean,
    onChange: (checked: boolean) => void
  ) => (
    <label className="flex items-start space-x-4 p-3 rounded-2xl border border-gray-100 hover:bg-gray-50/50 transition-colors cursor-pointer select-none">
      <div className="pt-1.5 shrink-0">
        <input
          type="checkbox"
          checked={checked}
          onChange={(event) => onChange(event.target.checked)}
          className="w-4.5 h-4.5 rounded border-gray-300 text-brand-primary focus:ring-brand-primary cursor-pointer accent-brand-primary"
        />
      </div>
      <div className="flex-1">
        <div className="flex justify-between items-center">
          <span className="text-sm font-bold text-gray-800">{label}</span>
          <span className={`text-[10px] font-bold px-2 py-0.5 rounded ${checked ? 'text-brand-accent-hover bg-brand-accent/10' : 'text-gray-400 bg-gray-100'}`}>
            {checked ? 'Ativo' : 'Inativo'}
          </span>
        </div>
        <p className="text-xs text-gray-500 mt-1 leading-relaxed">{description}</p>
      </div>
    </label>
  );

  if (!ready) return null;

  const showFloatingPrivacyWidget = isPublicPrivacyWidgetPath(location.pathname);

  return (
    <>
      {!visible && showFloatingPrivacyWidget && (
        <button
          type="button"
          onClick={() => window.dispatchEvent(new Event('cookie-consent-open'))}
          className="app-cookie-floating fixed left-4 z-[60] hidden h-10 items-center gap-2 rounded-full border border-brand-border/70 bg-white/95 px-3 text-xs font-semibold text-brand-primary shadow-md backdrop-blur-sm transition-all hover:-translate-y-0.5 hover:border-brand-primary/30 hover:shadow-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-primary focus-visible:ring-offset-2 md:inline-flex"
          aria-label="Abrir preferências de privacidade e cookies"
          title="Privacidade e cookies"
        >
          <Cookie className="h-4 w-4" aria-hidden="true" />
          <span>Privacidade e cookies</span>
        </button>
      )}

      {visible && !preferencesOpen && (
        <div className="app-safe-bottom fixed left-0 right-0 bg-white border-t border-gray-100 p-4 z-[70] shadow-2xl">
          <div className="max-w-5xl mx-auto flex flex-col md:flex-row items-center justify-between gap-4">
            <p className="text-sm text-gray-600 leading-relaxed">
              Usamos tecnologias opcionais somente com sua autorização para medir desempenho e, separadamente, ativar recursos de publicidade.
            </p>
            <div className="flex gap-3 shrink-0 w-full md:w-auto">
              <button onClick={() => setPreferencesOpen(true)} className="flex-1 md:flex-none px-6 py-2.5 border border-gray-200 text-gray-600 rounded-xl font-semibold text-sm">
                Preferências
              </button>
              <button onClick={() => save(true, true)} className="flex-1 md:flex-none bg-brand-primary text-white px-8 py-2.5 rounded-xl font-bold text-sm">
                Aceitar Todos
              </button>
            </div>
          </div>
        </div>
      )}

      {preferencesOpen && (
        <div className="fixed inset-0 bg-stone-900/60 backdrop-blur-sm flex items-center justify-center p-4 z-[80]">
          <div
            className="bg-white rounded-3xl border border-gray-100 shadow-2xl max-w-lg w-full p-6 space-y-6"
            role="dialog"
            aria-modal="true"
            aria-labelledby="privacy-preferences-title"
          >
            <div className="flex items-center space-x-3 border-b border-gray-100 pb-4">
              <div className="p-2.5 bg-brand-primary/10 rounded-xl text-brand-primary">
                <Shield className="w-5 h-5" aria-hidden="true" />
              </div>
              <div>
                <h3 id="privacy-preferences-title" className="text-lg font-bold font-display text-brand-primary">
                  Preferências de privacidade
                </h3>
                <p className="text-xs text-gray-500">Você pode alterar estas escolhas a qualquer momento.</p>
              </div>
            </div>

            <div className="space-y-4 max-h-[300px] overflow-y-auto pr-1">
              <div className="flex items-start space-x-4 p-3 rounded-2xl bg-gray-50/80 border border-gray-100">
                <div className="p-2 bg-brand-primary/10 rounded-lg text-brand-primary mt-0.5">
                  <Check className="w-4 h-4" aria-hidden="true" />
                </div>
                <div>
                  <div className="flex justify-between items-center">
                    <span className="text-sm font-bold text-gray-800">Essenciais (obrigatório)</span>
                    <span className="text-[10px] font-bold text-brand-primary bg-brand-primary/10 px-2 py-0.5 rounded">Ativo</span>
                  </div>
                  <p className="text-xs text-gray-500 mt-1">Autenticação, segurança e suas preferências.</p>
                </div>
              </div>
              {item('Estatísticas & Analytics', 'Medição com Firebase/GA4, sem conteúdo clínico; pode usar identificadores pseudônimos.', analytics, setAnalytics)}
              {item('Marketing', 'Google Ads/remarketing e Meta Pixel, quando configurados, sem conteúdo clínico.', marketing, setMarketing)}
            </div>

            <Link
              to="/privacy"
              onClick={closePreferences}
              className="inline-flex items-center gap-1.5 text-xs font-semibold text-brand-primary hover:underline"
            >
              Ler a Política de Privacidade
              <ExternalLink className="h-3.5 w-3.5" aria-hidden="true" />
            </Link>

            <div className="flex flex-col-reverse gap-3 border-t border-gray-100 pt-4 sm:flex-row sm:items-center sm:justify-between">
              <button onClick={closePreferences} className="px-5 py-2.5 border border-gray-200 text-gray-500 rounded-xl font-semibold text-xs">
                Voltar
              </button>
              <div className="flex gap-2">
                <button onClick={() => save(true, true)} className="flex-1 px-5 py-2.5 border border-brand-primary/20 text-brand-primary rounded-xl font-bold text-xs sm:flex-none">
                  Aceitar Todos
                </button>
                <button onClick={() => save()} className="flex-1 bg-brand-primary text-white px-5 py-2.5 rounded-xl font-bold text-xs sm:flex-none">
                  Salvar escolhas
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

src/components/Layout.tsx:
import React, { useState, useEffect } from 'react';
import { Outlet, Link, useNavigate, useLocation } from 'react-router-dom';
import { supabase } from '../supabaseClient';
import { useAuthStore } from '../store/authStore';
import { useSiteConfig } from '../hooks/useSiteConfig';
import { LayoutDashboard, Users, History as HistoryIcon, LogOut, Menu, X, Download, BookOpen, Share2, ShieldCheck, CreditCard, User, Bell, HelpCircle, ChevronLeft, ChevronRight, Database, Crown, Lightbulb, Info, Image, Cloud } from 'lucide-react';
import { UserAvatar } from './common/UserAvatar';
import { appendBrandAssetVersion, getBrandAssetSignature, getBrandIconUrl } from '../utils/brandAssets';
import { OfflineQueueMonitor } from './layout/OfflineQueueMonitor';
import TrialBanner from './layout/TrialBanner';
import { runAutoBackupIfNeeded } from '../services/backupService';
import { hasActiveYearlyAccess } from '../utils/subscriptionAccess';
import { isAndroidDevice, redirectToGooglePlay } from '../utils/googlePlay';
import { showAlert } from '../store/modalStore';

export default function Layout() {
  const { user, profileRole, googleAccessToken, subscriptionPlan, subscriptionStatus, subscriptionEndsAt } = useAuthStore();
  const siteConfig = useSiteConfig();
  const navigate = useNavigate();
  const location = useLocation();
  const assetSignature = getBrandAssetSignature(siteConfig);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isStandalone, setIsStandalone] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const isNativeWebView = typeof navigator !== 'undefined' && /EvolucaoClinicaApp/i.test(navigator.userAgent);
  const hasYearlyAccess = hasActiveYearlyAccess({
    profileRole,
    subscriptionPlan,
    subscriptionStatus,
    subscriptionEndsAt
  });
  const [isCollapsed, setIsCollapsed] = useState(() => {
    return window.innerWidth >= 768 && window.innerWidth < 1024;
  });

  useEffect(() => {
    const checkStandalone = () => {
      const standalone =
        window.matchMedia('(display-mode: standalone)').matches ||
        (navigator as any).standalone === true;
      setIsStandalone(standalone);
    };

    checkStandalone();

    const handleBeforeInstallPrompt = (event: Event) => {
      event.preventDefault();
      setDeferredPrompt(event);
    };

    const handleAppInstalled = () => {
      setDeferredPrompt(null);
      setIsStandalone(true);
    };

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    window.addEventListener('appinstalled', handleAppInstalled);

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
      window.removeEventListener('appinstalled', handleAppInstalled);
    };
  }, []);

  useEffect(() => {
    if (!user) return;

    const fetchUnreadCount = async () => {
      try {
        const { count, error } = await supabase
          .from('notifications')
          .select('*', { count: 'exact', head: true })
          .eq('user_id', user.id)
          .is('read_at', null);

        if (!error && count !== null) {
          setUnreadCount(count);
        }
      } catch (err) {
        console.error('Erro ao buscar contagem de nao lidas:', err);
      }
    };

    fetchUnreadCount();

    // Realtime subscription para atualizar contagem instantaneamente
    const channel = supabase
      .channel('layout-notifications-count')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'notifications', filter: `user_id=eq.${user.id}` },
        () => {
          fetchUnreadCount();
        }
      )
      .subscribe();

    return () => {
      void supabase.removeChannel(channel);
    };
  }, [user]);

  useEffect(() => {
    if (!user || !googleAccessToken || !hasYearlyAccess) return;

    const triggerBackup = async () => {
      try {
        await runAutoBackupIfNeeded(user.id, googleAccessToken, user.user_metadata?.full_name || 'Terapeuta');
      } catch (err) {
        console.error('[Layout] Falha ao executar backup em background:', err);
      }
    };

    const timer = setTimeout(triggerBackup, 5000);
    return () => clearTimeout(timer);
  }, [user, googleAccessToken, hasYearlyAccess]);

  useEffect(() => {
    if (!isMobileMenuOpen) return;

    const htmlOverscrollBehavior = document.documentElement.style.overscrollBehaviorY;
    const bodyOverscrollBehavior = document.body.style.overscrollBehaviorY;
    document.documentElement.style.overscrollBehaviorY = 'none';
    document.body.style.overscrollBehaviorY = 'none';

    return () => {
      document.documentElement.style.overscrollBehaviorY = htmlOverscrollBehavior;
      document.body.style.overscrollBehaviorY = bodyOverscrollBehavior;
    };
  }, [isMobileMenuOpen]);

  const handleInstallClick = async () => {
    if (isAndroidDevice()) {
      redirectToGooglePlay();
      return;
    }

    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') {
        console.log('User accepted the install prompt');
      }
      setDeferredPrompt(null);
    } else {
      const isIOS = () => {
        if (typeof navigator === 'undefined') return false;
        return /iPad|iPhone|iPod/.test(navigator.userAgent) || 
               (/Macintosh/.test(navigator.userAgent) && 'ontouchend' in document);
      };
      const iosDevice = isIOS();
      if (iosDevice) {
        await showAlert(
          "Para instalar o aplicativo no seu iPhone/iPad:\n\n1. Toque no ícone de Compartilhar (no rodapé do Safari ou topo do iPad).\n2. Role a lista de opções para baixo e selecione 'Adicionar à Tela de Início'.\n3. Confirme tocando em 'Adicionar' no canto superior direito.",
          {
            title: "Instalar Aplicativo (iOS)",
            confirmLabel: "Entendi",
            variant: "info",
            icon: "download"
          }
        );
      } else {
        await showAlert(
          "Para instalar o aplicativo no seu navegador:\n\n1. Clique no menu do navegador (geralmente o ícone de três pontos ou traços no canto superior direito).\n2. Selecione 'Instalar aplicativo' ou 'Adicionar à tela inicial'.\n3. Confirme a instalação.",
          {
            title: "Instalar Aplicativo",
            confirmLabel: "Entendi",
            variant: "info",
            icon: "download"
          }
        );
      }
    }
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
    navigate('/login');
  };

  const navItems = [
    { name: 'Dashboard', path: '/painel/dashboard', icon: LayoutDashboard },
    { name: 'Pacientes', path: '/painel/patients', icon: Users },
    { name: 'Histórico', path: '/painel/history', icon: HistoryIcon },
    { name: 'Como Usar', path: '/painel/tutorial', icon: BookOpen },
    { name: 'Notificações', path: '/painel/notifications', icon: Bell },
    { name: 'Migração de Prontuários', path: '/painel/migration', icon: Database, isPremium: true },
    { name: 'Logotipo Personalizado', path: '/painel/logotipo-personalizado', icon: Image, isPremium: true },
    { name: 'Backup e Exportação', path: '/painel/backup-exportacao', icon: Cloud, isPremium: true },
    { name: 'Sugestões', path: '/painel/sugestoes', icon: Lightbulb },
    { name: 'Meu Perfil', path: '/painel/profile', icon: User },
    { name: 'Assinatura', path: '/painel/subscription', icon: CreditCard },
  ];

  if (profileRole === 'admin') {
    navItems.push({ name: 'Painel Admin', path: '/admin', icon: ShieldCheck });
  }

  navItems.push({ name: 'Sobre o app', path: '/painel/about', icon: Info });

  const bottomNavItems = [
    { name: 'Início', path: '/painel/dashboard', icon: LayoutDashboard },
    { name: 'Pacientes', path: '/painel/patients', icon: Users },
    { name: 'Histórico', path: '/painel/history', icon: HistoryIcon },
    { name: 'Notif.', path: '/painel/notifications', icon: Bell },
    { name: 'Mais', path: '#menu', icon: Menu },
  ];

  return (
    <div className="min-h-screen bg-brand-bg flex flex-col md:flex-row">

      {/* Sidebar */}
      <div
        onClick={(event) => {
          if ((event.target as HTMLElement).closest('a, button, input, select, textarea, [role="button"]')) return;
          setIsCollapsed((collapsed) => !collapsed);
        }}
        className={`
        hidden md:flex flex-col bg-white border-r border-brand-border flex-shrink-0
        z-40 self-stretch shadow-sm
        transition-all duration-300 md:relative overflow-y-auto md:overflow-y-visible
        ${isCollapsed ? 'w-20' : 'w-64'} cursor-pointer
      `}
      >
        {/* Toggle Collapse Button - Only visible on desktop/tablet (md) */}
        <button
          onClick={(event) => {
            event.stopPropagation();
            setIsCollapsed((collapsed) => !collapsed);
          }}
          className="hidden md:flex absolute -right-3 top-6 z-50 bg-white border border-brand-border rounded-full p-1 shadow-md hover:bg-brand-bg transition-all cursor-pointer items-center justify-center text-brand-primary"
          title={isCollapsed ? "Expandir menu" : "Recolher menu"}
        >
          {isCollapsed ? <ChevronRight size={14} /> : <ChevronLeft size={14} />}
        </button>

        <div className="flex-1 md:overflow-y-auto overflow-y-visible overflow-x-hidden no-scrollbar-x">
          <div className="p-4 hidden md:block border-b border-brand-border/50">
            <Link to="/" className="flex justify-center">
              {isCollapsed ? (
                <img
                  src={appendBrandAssetVersion(getBrandIconUrl(siteConfig), assetSignature)}
                  alt={siteConfig.pwa_app_name || "Evolução Clínica"}
                  className="h-10 w-10 object-contain"
                />
              ) : (
                (siteConfig.logo_light_url || siteConfig.logo_dark_url) ? (
                  <img
                    src={appendBrandAssetVersion(siteConfig.logo_light_url || siteConfig.logo_dark_url, assetSignature)}
                    alt={siteConfig.pwa_app_name || "Evolução Clínica"}
                    className="h-28 w-auto max-w-full object-contain"
                  />
                ) : (
                  <span className="text-xl font-display font-bold text-brand-primary py-4 block text-center">
                    {siteConfig.pwa_app_name || "Evolução Clínica"}
                  </span>
                )
              )}
            </Link>
          </div>

          <div className={`${isCollapsed ? 'px-2' : 'px-4'} py-6`}>
            <div className={`flex items-center mb-6 bg-brand-bg rounded-xl border border-brand-border/50 ${isCollapsed ? 'justify-center p-2' : 'space-x-3 px-4 py-3'}`}>
              <UserAvatar
                name={user?.user_metadata?.full_name || user?.user_metadata?.name}
                email={user?.email}
                src={user?.user_metadata?.avatar_url || user?.user_metadata?.picture || user?.user_metadata?.photo_url}
                className="h-10 w-10 border border-brand-border"
                title={isCollapsed ? (user?.user_metadata?.full_name || user?.email || 'Profissional') : undefined}
              />
              {!isCollapsed && (
                <div className="overflow-hidden">
                  <p className="text-sm font-medium text-brand-text truncate">{user?.user_metadata?.full_name || user?.email || 'Profissional'}</p>
                  <p className="text-xs text-brand-text-muted truncate">{user?.email}</p>
                </div>
              )}
            </div>

            <nav className="space-y-1">
              {navItems.map((item) => {
                const Icon = item.icon;
                const isActive = location.pathname === item.path || (item.path !== '/painel/dashboard' && location.pathname.startsWith(item.path));
                return (
                  <Link
                    key={item.name}
                    to={item.path}
                    onClick={() => setIsMobileMenuOpen(false)}
                    title={isCollapsed ? item.name : undefined}
                    className={`flex items-center rounded-xl transition-all duration-200 relative group ${
                      isCollapsed 
                        ? 'justify-center p-2.5'
                        : 'justify-between px-4 py-2.5'
                    } ${
                      isActive 
                        ? 'bg-brand-primary text-white shadow-sm' 
                        : 'text-brand-text-muted hover:bg-brand-bg hover:text-brand-primary'
                    }`}
                  >
                    <div className={`flex items-center ${isCollapsed ? 'justify-center' : 'space-x-3'}`}>
                      <div className="relative">
                        <Icon size={20} className="flex-shrink-0" />
                        {item.name === 'Notificações' && unreadCount > 0 && isCollapsed && (
                          <span className="absolute -top-1.5 -right-1.5 bg-red-500 text-white text-[8px] font-bold w-4 h-4 rounded-full flex items-center justify-center border border-white animate-pulse">
                            {unreadCount}
                          </span>
                        )}
                        {item.isPremium && isCollapsed && (
                          <span className="absolute -top-1.5 -right-1.5 bg-amber-500 text-white w-3.5 h-3.5 rounded-full flex items-center justify-center border border-white shadow-sm" title="Premium (Plano Anual)">
                            <Crown size={8} className="fill-white" />
                          </span>
                        )}
                      </div>
                      {!isCollapsed && <span className="font-medium">{item.name}</span>}
                    </div>
                    {item.name === 'Notificações' && unreadCount > 0 && !isCollapsed && (
                      <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                        isActive ? 'bg-white text-brand-primary' : 'bg-brand-primary text-white animate-pulse'
                      }`}>
                        {unreadCount}
                      </span>
                    )}
                    {item.isPremium && !isCollapsed && (
                      <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-md flex items-center shrink-0 ${
                        isActive 
                          ? 'bg-white/20 text-white' 
                          : 'bg-amber-50 text-amber-600 border border-amber-200'
                      }`} title="Recurso Premium do Plano Anual">
                        <Crown size={10} className="fill-current shrink-0" />
                      </span>
                    )}
                  </Link>
                );
              })}
            </nav>

          </div>
        </div>

        <div className={`${isCollapsed ? 'p-2' : 'p-4'} border-t border-brand-border bg-white space-y-1`}>
          {!isStandalone && !isNativeWebView && (
            <button
              onClick={handleInstallClick}
              title={isCollapsed ? "Instalar App" : undefined}
              className={`flex items-center rounded-xl text-brand-primary bg-brand-primary/10 hover:bg-brand-primary/20 transition-all duration-200 relative group ${
                isCollapsed ? 'justify-center p-2.5 w-full' : 'space-x-3 px-4 py-2.5 w-full'
              }`}
            >
              <Download size={20} className="flex-shrink-0" />
              {!isCollapsed && <span className="font-medium">Instalar App</span>}
            </button>
          )}
          <div className="w-full">
            <button
              onClick={() => {
                const text = "Olá! Estou usando o aplicativo Evolução Clínica para gerenciar meus prontuários com IA e achei fantástico. Facilita muito o dia a dia! Dá uma olhada: " + window.location.origin;
                window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
              }}
              title={isCollapsed ? "Indique o App" : undefined}
              className={`flex items-center rounded-xl text-brand-primary hover:bg-brand-primary/10 hover:text-brand-primary-hover transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] cursor-pointer relative group ${
                isCollapsed ? 'justify-center p-2.5 w-full' : 'space-x-3 px-4 py-2.5 w-full'
              }`}
            >
              <Share2 size={20} className="flex-shrink-0" />
              {!isCollapsed && <span className="font-medium">Indique o App</span>}
            </button>
            {!isCollapsed && (
              <span className="text-[10px] text-brand-text-muted pl-12 block -mt-1 mb-2">
                Compartilhamento via WhatsApp
              </span>
            )}
          </div>
          <button
            onClick={handleLogout}
            title={isCollapsed ? "Sair" : undefined}
            className={`flex items-center rounded-xl text-red-600 hover:bg-red-50 transition-colors relative group ${
              isCollapsed ? 'justify-center p-2.5 w-full' : 'space-x-3 px-4 py-2.5 w-full'
            }`}
          >
            <LogOut size={20} className="flex-shrink-0" />
            {!isCollapsed && <span className="font-medium">Sair</span>}
          </button>
        </div>
      </div>

      {/* Main Content */}
      <div className="app-main-content flex-1 overflow-x-hidden flex flex-col">
        <TrialBanner />
        <main className="w-full max-w-[1440px] p-4 md:p-8 mx-auto flex-1 [&>div]:w-full [&>div]:max-w-none">
          <Outlet />
        </main>
      </div>

      {/* Mobile Full Screen Menu Overlay */}
      <div className={`
        fixed inset-0 z-[100] bg-white flex flex-col overscroll-y-none md:hidden
        transition-all duration-300 ease-out origin-bottom-right
        ${isMobileMenuOpen 
          ? 'opacity-100 scale-100 translate-x-0 translate-y-0 pointer-events-auto' 
          : 'opacity-0 scale-0 translate-x-1/4 translate-y-1/4 pointer-events-none'
        }
      `}>
        {/* Mobile Menu Header */}
        <div className="app-mobile-menu-header bg-white border-b border-brand-border/60 flex justify-between items-center shrink-0">
          {(siteConfig.logo_light_url || siteConfig.logo_dark_url) ? (
            <img
              src={appendBrandAssetVersion(siteConfig.logo_light_url || siteConfig.logo_dark_url, assetSignature)}
              alt={siteConfig.pwa_app_name || "Evolução Clínica"}
              className="h-12 w-auto max-w-[140px] object-contain"
            />
          ) : (
            <span className="text-lg font-display font-bold text-brand-primary">
              {siteConfig.pwa_app_name || "Evolução Clínica"}
            </span>
          )}
          <button 
            onClick={() => setIsMobileMenuOpen(false)} 
            className="p-2 text-brand-primary hover:bg-brand-bg rounded-lg cursor-pointer"
            title="Fechar menu"
          >
            <X size={24} />
          </button>
        </div>

        {/* Mobile Menu Content */}
        <div className="app-mobile-menu-content flex-1 overflow-y-auto p-4 space-y-6">
          {/* User Profile Info Card */}
          <div className="flex items-center space-x-3 p-4 bg-brand-bg rounded-xl border border-brand-border/50">
            <UserAvatar
              name={user?.user_metadata?.full_name || user?.user_metadata?.name}
              email={user?.email}
              src={user?.user_metadata?.avatar_url || user?.user_metadata?.picture || user?.user_metadata?.photo_url}
              className="h-12 w-12 border border-brand-border"
            />
            <div className="overflow-hidden">
              <p className="text-sm font-medium text-brand-text truncate">{user?.user_metadata?.full_name || user?.email || 'Profissional'}</p>
              <p className="text-xs text-brand-text-muted truncate">{user?.email}</p>
            </div>
          </div>

          {/* Navigation Links */}
          <nav className="space-y-0.5">
            {navItems.map((item) => {
              const Icon = item.icon;
              const isActive = location.pathname === item.path || (item.path !== '/painel/dashboard' && location.pathname.startsWith(item.path));
              return (
                <Link
                  key={item.name}
                  to={item.path}
                  onClick={() => setIsMobileMenuOpen(false)}
                  className={`flex items-center justify-between px-4 py-2.5 rounded-xl transition-all duration-200 relative group ${
                    isActive 
                      ? 'bg-brand-primary text-white shadow-sm' 
                      : 'text-brand-text-muted hover:bg-brand-bg hover:text-brand-primary'
                  }`}
                >
                  <div className="flex items-center space-x-3">
                    <Icon size={20} className="flex-shrink-0" />
                    <span className="font-medium text-sm">{item.name}</span>
                  </div>

                  {item.name === 'Notificações' && unreadCount > 0 && (
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                      isActive ? 'bg-white text-brand-primary' : 'bg-brand-primary text-white animate-pulse'
                    }`}>
                      {unreadCount}
                    </span>
                  )}
                  {item.isPremium && (
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-md flex items-center shrink-0 ${
                      isActive 
                        ? 'bg-white/20 text-white' 
                        : 'bg-amber-50 text-amber-600 border border-amber-200'
                    }`} title="Recurso Premium do Plano Anual">
                      <Crown size={10} className="fill-current shrink-0" />
                    </span>
                  )}
                </Link>
              );
            })}
          </nav>

          {/* Actions & Utilities */}
          <div className="pt-3 border-t border-brand-border/60 space-y-1">
            {!isStandalone && !isNativeWebView && (
              <button
                onClick={handleInstallClick}
                className="flex items-center space-x-3 px-4 py-2.5 w-full rounded-xl text-brand-primary bg-brand-primary/10 hover:bg-brand-primary/20 transition-all duration-200 cursor-pointer"
              >
                <Download size={20} className="flex-shrink-0" />
                <span className="font-medium text-sm">Instalar App</span>
              </button>
            )}
            <button
              onClick={() => {
                const text = "Olá! Estou usando o aplicativo Evolução Clínica para gerenciar meus prontuários com IA e achei fantástico. Facilita muito o dia a dia! Dá uma olhada: " + window.location.origin;
                window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
              }}
              className="flex items-center space-x-3 px-4 py-2.5 w-full rounded-xl text-brand-primary hover:bg-brand-bg transition-all duration-200 cursor-pointer animate-none"
            >
              <Share2 size={20} className="flex-shrink-0" />
              <span className="font-medium text-sm">Indique o App</span>
            </button>
            <button
              onClick={handleLogout}
              className="flex items-center space-x-3 px-4 py-2.5 w-full rounded-xl text-red-600 hover:bg-red-50 transition-colors cursor-pointer"
            >
              <LogOut size={20} className="flex-shrink-0" />
              <span className="font-medium text-sm">Sair</span>
            </button>
          </div>
        </div>
      </div>

      {/* Fila de Sincronização Offline */}
      <OfflineQueueMonitor />

      {/* Menu Inferior Mobile */}
      <div className="app-mobile-bottom-nav md:hidden fixed left-0 right-0 z-50 bg-white/95 backdrop-blur-md border-t border-brand-border/60 shadow-lg flex justify-around items-center">
        {bottomNavItems.map((item) => {
          const Icon = item.icon;
          const isMais = item.name === 'Mais';

          const isFirst4Active = bottomNavItems
            .slice(0, 4)
            .some(nav => location.pathname === nav.path || (nav.path !== '/painel/dashboard' && location.pathname.startsWith(nav.path)));
          const isActive = isMais 
            ? (isMobileMenuOpen || !isFirst4Active)
            : (location.pathname === item.path || (item.path !== '/painel/dashboard' && location.pathname.startsWith(item.path)));

          if (isMais) {
            return (
              <button
                key={item.name}
                onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                className={`flex flex-col items-center justify-center flex-1 py-1 transition-all duration-200 cursor-pointer ${
                  isActive 
                    ? 'text-brand-primary font-semibold scale-105' 
                    : 'text-brand-text-muted hover:text-brand-primary'
                }`}
              >
                <div className="relative">
                  <Icon size={20} className={isActive ? 'stroke-[2.5px]' : 'stroke-[1.8px]'} />
                </div>
                <span className="text-[10px] mt-1 font-sans">Mais</span>
              </button>
            );
          }

          return (
            <Link
              key={item.name}
              to={item.path}
              className={`flex flex-col items-center justify-center flex-1 py-1 transition-all duration-200 ${
                isActive 
                  ? 'text-brand-primary font-semibold scale-105' 
                  : 'text-brand-text-muted hover:text-brand-primary'
              }`}
            >
              <div className="relative">
                <Icon size={20} className={isActive ? 'stroke-[2.5px]' : 'stroke-[1.8px]'} />
                {item.name === 'Notif.' && unreadCount > 0 && (
                  <span className="absolute -top-1.5 -right-1.5 bg-red-500 text-white text-[8px] font-bold w-4 h-4 rounded-full flex items-center justify-center border border-white">
                    {unreadCount}
                  </span>
                )}
              </div>
              <span className="text-[10px] mt-1 font-sans">{item.name}</span>
            </Link>
          );
        })}
      </div>
    </div>
  );
}

src/components/admin/AdminConversionFunn:
import { useCallback, useEffect, useState } from 'react';
import { AlertTriangle, ArrowRight, CheckCircle2, CreditCard, Loader2, RefreshCw, Users } from 'lucide-react';
import { supabase } from '../../supabaseClient';

type Funnel = {
  generatedAt: string;
  stages: Record<string, number>;
  rates: Record<string, number>;
  blockers: { googleScopeErrors: number };
  checkout: { users: number; total: number; byStatus: Record<string, number> };
};

const STAGES = [
  ['registered', 'Cadastros'],
  ['whatsappVerified', 'WhatsApp verificado'],
  ['withPatient', 'Primeiro paciente'],
  ['withLinkedRecord', 'Prontuário vinculado'],
  ['withFirstEvolution', 'Primeira evolução'],
  ['returnedSecondDay', 'Retorno em outro dia'],
  ['paid', 'Plano pago'],
] as const;

export function AdminConversionFunnel() {
  const [funnel, setFunnel] = useState<Funnel | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const { data: session } = await supabase.auth.getSession();
      const token = session.session?.access_token;
      if (!token) throw new Error('Sessão expirada.');
      const response = await fetch('/api/admin/conversion-funnel?days=30', { headers: { Authorization: `Bearer ${token}` } });
      const payload = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(payload.error || 'Falha ao carregar funil.');
      setFunnel(payload);
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : 'Falha ao carregar funil.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  const registered = funnel?.stages.registered || 0;

  return (
    <section className="mb-6 rounded-3xl border border-brand-primary/15 bg-white p-5 shadow-sm sm:p-6" data-testid="admin-conversion-funnel">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <div className="flex items-center gap-2 text-brand-primary"><Users size={18} /><h2 className="font-display text-lg font-bold">Funil de ativação — últimos 30 dias</h2></div>
          <p className="mt-1 text-xs text-brand-text-muted">Coorte comercial, sem administradores e planos cortesia.</p>
        </div>
        <button type="button" onClick={() => void load()} disabled={loading} className="btn-outline inline-flex items-center justify-center gap-2 px-4 py-2 text-xs">
          <RefreshCw size={14} className={loading ? 'animate-spin' : ''} /> Atualizar
        </button>
      </div>

      {loading && !funnel ? (
        <div className="flex min-h-32 items-center justify-center gap-2 text-sm text-brand-text-muted"><Loader2 className="animate-spin" size={20} />Carregando...</div>
      ) : error ? (
        <div className="mt-5 rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{error}</div>
      ) : funnel ? (
        <>
          <div className="mt-5 grid gap-2 sm:grid-cols-2 xl:grid-cols-7">
            {STAGES.map(([key, label], index) => {
              const value = funnel.stages[key] || 0;
              const percentage = registered > 0 ? Math.round((value / registered) * 100) : 0;
              return (
                <div key={key} className="relative rounded-2xl border border-brand-border/60 bg-brand-bg/20 p-3">
                  <p className="text-[10px] font-bold uppercase tracking-wide text-brand-text-muted">{label}</p>
                  <p className="mt-1 text-2xl font-bold text-brand-primary">{value}</p>
                  <p className="text-[11px] text-brand-text-muted">{percentage}% da coorte</p>
                  {index < STAGES.length - 1 && <ArrowRight className="absolute -right-2.5 top-1/2 z-10 hidden -translate-y-1/2 rounded-full bg-white text-brand-border xl:block" size={18} />}
                </div>
              );
            })}
          </div>

          <div className="mt-4 grid gap-3 md:grid-cols-3">
            <div className="rounded-2xl border border-emerald-200 bg-emerald-50 p-4">
              <p className="flex items-center gap-2 text-xs font-bold text-emerald-800"><CheckCircle2 size={15} />Primeira evolução em até 48h</p>
              <p className="mt-1 text-xl font-bold text-emerald-900">{funnel.rates.firstEvolutionWithin48h || 0}%</p>
            </div>
            <div className="rounded-2xl border border-amber-200 bg-amber-50 p-4">
              <p className="flex items-center gap-2 text-xs font-bold text-amber-800"><AlertTriangle size={15} />Erros de permissão Google</p>
              <p className="mt-1 text-xl font-bold text-amber-900">{funnel.blockers.googleScopeErrors}</p>
            </div>
            <div className="rounded-2xl border border-sky-200 bg-sky-50 p-4">
              <p className="flex items-center gap-2 text-xs font-bold text-sky-800"><CreditCard size={15} />Tentativas de checkout</p>
              <p className="mt-1 text-xl font-bold text-sky-900">{funnel.checkout.total}</p>
              <p className="text-[11px] text-sky-800">{funnel.checkout.users} profissionais · {funnel.checkout.byStatus.paid || 0} pagas · {funnel.checkout.byStatus.failed || 0} falhas · {funnel.checkout.byStatus.cancelled || 0} canceladas</p>
            </div>
          </div>
        </>
      ) : null}
    </section>
  );
}

src/components/admin/DailyPushNotificati:
import React, { useState, useEffect } from 'react';
import { supabase } from '../../supabaseClient';
import { showAlert } from '../../store/modalStore';
import { useSiteConfig } from '../../hooks/useSiteConfig';
import { getBrandPushNotificationIconUrl } from '../../utils/brandAssets';
import { 
  Bell, Save, Play, Loader2, Check, AlertTriangle, 
  HelpCircle, Calendar, Clock, Upload, Trash2, Smartphone, 
  ChevronRight, AlignLeft, Link as LinkIcon, Image as ImageIcon,
  History, RefreshCw
} from 'lucide-react';

interface DailyPushConfig {
  enabled: boolean;
  days: number[];
  time: string;
  title: string;
  body: string;
  image_url: string;
  icon_url: string;
  destination_url: string;
  last_sent_date?: string;
  server_time_utc?: string;
  server_time_br?: string;
}

interface PushLog {
  id: string;
  sent_at: string;
  status: 'success' | 'error';
  recipients_count: number;
  error_message?: string;
  payload: {
    title?: string;
    body?: string;
    link?: string;
    image?: string;
    icon?: string;
  };
}

const WEEKDAYS = [
  { val: 1, label: 'Segunda-feira', short: 'Seg' },
  { val: 2, label: 'Terça-feira', short: 'Ter' },
  { val: 3, label: 'Quarta-feira', short: 'Qua' },
  { val: 4, label: 'Quinta-feira', short: 'Qui' },
  { val: 5, label: 'Sexta-feira', short: 'Sex' },
  { val: 6, label: 'Sábado', short: 'Sáb' },
  { val: 0, label: 'Domingo', short: 'Dom' }
];

export default function DailyPushNotificationManager() {
  const siteConfig = useSiteConfig();
  const [config, setConfig] = useState<DailyPushConfig>({
    enabled: false,
    days: [1, 2, 3, 4, 5],
    time: '08:00',
    title: '⏰ Hora das Evoluções!',
    body: 'Não esqueça de registrar as evoluções clínicas de hoje.',
    image_url: '',
    icon_url: '',
    destination_url: '/painel/patients'
  });

  const displayIconUrl = config.icon_url || getBrandPushNotificationIconUrl(siteConfig);

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [testing, setTesting] = useState(false);
  const [message, setMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

  const [uploadingImage, setUploadingImage] = useState(false);
  const [uploadingIcon, setUploadingIcon] = useState(false);

  const [history, setHistory] = useState<PushLog[]>([]);
  const [historyLoading, setHistoryLoading] = useState(false);

  useEffect(() => {
    fetchConfig();
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    setHistoryLoading(true);
    try {
      const session = await supabase.auth.getSession();
      const token = session.data.session?.access_token;
      if (!token) return;

      const res = await fetch(`/api/admin/daily-push-history?t=${Date.now()}`, {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      if (res.ok) {
        const data = await res.json();
        if (Array.isArray(data)) {
          setHistory(data);
        } else {
          setHistory([]);
        }
      } else {
        setHistory([]);
      }
    } catch (err) {
      console.error('Erro ao carregar histórico de push:', err);
      setHistory([]);
    } finally {
      setHistoryLoading(false);
    }
  };

  const fetchConfig = async () => {
    setLoading(true);
    try {
      const session = await supabase.auth.getSession();
      const token = session.data.session?.access_token;
      if (!token) return;

      const res = await fetch(`/api/admin/daily-push-config?t=${Date.now()}`, {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      if (res.ok) {
        const data = await res.json();
        setConfig(data);
      }
    } catch (err) {
      console.error('Erro ao carregar configurações de push diário:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    setMessage(null);
    try {
      const session = await supabase.auth.getSession();
      const token = session.data.session?.access_token;
      if (!token) throw new Error('Não autenticado.');

      const res = await fetch('/api/admin/daily-push-config', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(config)
      });

      if (res.ok) {
        setMessage({ type: 'success', text: 'Configuração salva com sucesso!' });
      } else {
        const errData = await res.json().catch(() => ({}));
        throw new Error(errData.error || 'Erro ao salvar configuração.');
      }
    } catch (err: any) {
      console.error('Erro ao salvar:', err);
      setMessage({ type: 'error', text: err.message || 'Erro ao salvar configuração.' });
    } finally {
      setSaving(false);
    }
  };

  const handleTestPush = async () => {
    setTesting(true);
    setMessage(null);
    try {
      const session = await supabase.auth.getSession();
      const token = session.data.session?.access_token;
      if (!token) throw new Error('Não autenticado.');

      const res = await fetch('/api/admin/daily-push-test', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(config)
      });

      const resData = await res.json().catch(() => ({}));

      if (res.ok) {
        setMessage({ type: 'success', text: resData.message || 'Push de teste disparado com sucesso!' });
      } else {
        throw new Error(resData.error || 'Erro ao disparar push de teste.');
      }
    } catch (err: any) {
      console.error('Erro no teste:', err);
      setMessage({ type: 'error', text: err.message || 'Erro ao testar push.' });
    } finally {
      setTesting(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, field: 'image' | 'icon') => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (field === 'image') setUploadingImage(true);
    else setUploadingIcon(true);

    try {
      const fileExt = file.name.split('.').pop();
      const fileName = `daily-push/${Math.random().toString(36).substring(2, 15)}_${Date.now()}.${fileExt}`;
      const filePath = `${fileName}`;

      const { error } = await supabase.storage
        .from('notifications')
        .upload(filePath, file, {
          cacheControl: '3600',
          upsert: false
        });

      if (error) throw error;

      const { data: publicUrlData } = supabase.storage
        .from('notifications')
        .getPublicUrl(filePath);

      if (publicUrlData?.publicUrl) {
        if (field === 'image') {
          setConfig(prev => ({ ...prev, image_url: publicUrlData.publicUrl }));
        } else {
          setConfig(prev => ({ ...prev, icon_url: publicUrlData.publicUrl }));
        }
      }
    } catch (err: any) {
      console.error('Erro ao fazer upload da imagem:', err);
      await showAlert('Erro ao fazer upload da imagem: ' + (err.message || 'Erro desconhecido'), {
        title: "Erro de Upload",
        variant: "danger",
        icon: "warning"
      });
    } finally {
      if (field === 'image') setUploadingImage(false);
      else setUploadingIcon(false);
      e.target.value = '';
    }
  };

  const toggleDay = (dayVal: number) => {
    const currentDays = config.days || [];
    const isSelected = currentDays.includes(dayVal);
    const newDays = isSelected
      ? currentDays.filter(d => d !== dayVal)
      : [...currentDays, dayVal].sort();
    setConfig({ ...config, days: newDays });
  };

  if (loading) {
    return (
      <div className="p-12 flex flex-col items-center justify-center text-brand-text-muted">
        <Loader2 className="w-8 h-8 text-brand-primary animate-spin mb-3" />
        <span className="text-sm">Carregando configurações da notificação diária...</span>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Banner Principal */}
      <div className="card p-6 bg-white shadow-sm border border-brand-border/60">
        <div className="flex items-center space-x-3">
          <div className="p-3 bg-brand-primary/10 rounded-xl text-brand-primary">
            <Bell className="w-6 h-6" />
          </div>
          <div>
            <h2 className="text-xl font-display font-bold text-brand-primary border-none p-0 pb-0">
              Lembrete de Evoluções Clínicas (Push Diário)
            </h2>
            <p className="text-xs text-brand-text-muted mt-0.5">
              Programe um lembrete fixo diário que será enviado a todos os profissionais ativos da plataforma lembrando-os de evoluir seus pacientes.
            </p>
          </div>
        </div>
      </div>

      {message && (
        <div className={`p-4 rounded-xl border text-sm flex gap-2.5 items-start ${
          message.type === 'success' 
            ? 'bg-emerald-50 border-emerald-100 text-emerald-800' 
            : 'bg-red-50 border-red-100 text-red-800'
        }`}>
          {message.type === 'success' ? (
            <Check className="w-5 h-5 text-emerald-600 flex-shrink-0 mt-0.5" />
          ) : (
            <AlertTriangle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
          )}
          <div>{message.text}</div>
        </div>
      )}

      {/* Grid Duas Colunas: Config + Mockup Mobile */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* Coluna Configuração (Left) */}
        <div className="lg:col-span-7 space-y-6">
          <div className="card p-6 bg-white shadow-sm border border-brand-border/60 space-y-6">

            {/* Status (Ativo / Inativo) */}
            <div className="flex items-center justify-between p-4 bg-brand-bg rounded-xl border border-brand-border/50">
              <div>
                <p className="text-sm font-bold text-brand-text">Status do Envio Automático</p>
                <p className="text-xs text-brand-text-muted mt-0.5">Ativar ou desativar o lembrete diário programado</p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input 
                  type="checkbox" 
                  checked={config.enabled}
                  onChange={e => setConfig({ ...config, enabled: e.target.checked })}
                  className="sr-only peer"
                />
                <div className="w-11 h-6 bg-stone-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-stone-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-brand-primary"></div>
              </label>
            </div>

            {/* Dias da Semana */}
            <div className="space-y-2">
              <label className="text-xs font-bold text-brand-text uppercase tracking-wider flex items-center gap-1.5">
                <Calendar size={14} className="text-brand-primary" />
                Dias de Envio
              </label>
              <p className="text-xs text-brand-text-muted">Selecione os dias em que a notificação diária será disparada.</p>
              <div className="flex flex-wrap gap-2 pt-1">
                {WEEKDAYS.map(day => {
                  const isSelected = (config.days || []).includes(day.val);
                  return (
                    <button
                      key={day.val}
                      type="button"
                      onClick={() => toggleDay(day.val)}
                      className={`px-3 py-2 text-xs font-semibold rounded-xl border transition-all cursor-pointer ${
                        isSelected 
                          ? 'bg-brand-primary text-white border-brand-primary shadow-sm'
                          : 'bg-white text-brand-text border-brand-border hover:border-brand-primary/30'
                      }`}
                    >
                      {day.short}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Horário */}
            <div className="space-y-2">
              <label className="text-xs font-bold text-brand-text uppercase tracking-wider flex items-center gap-1.5">
                <Clock size={14} className="text-brand-primary" />
                Horário do Envio
              </label>
              <p className="text-xs text-brand-text-muted">A que horas a notificação deve começar a ser disparada (fuso Brasília).</p>
              <input
                type="time"
                value={config.time}
                onChange={e => setConfig({ ...config, time: e.target.value })}
                className="input-field p-2.5 max-w-[200px]"
              />
              {config.server_time_br && (
                <div className="text-[11px] text-brand-text-muted mt-2 space-y-1.5 bg-stone-50 p-2.5 rounded-xl border border-brand-border/40 max-w-[400px]">
                  <div className="flex items-center gap-1.5">
                    <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse flex-shrink-0"></span>
                    <span>
                      Hora do Servidor (Brasília): <strong>{
                        new Date(config.server_time_br).toLocaleString('pt-BR', {
                          day: '2-digit',
                          month: '2-digit',
                          year: 'numeric',
                          hour: '2-digit',
                          minute: '2-digit',
                          second: '2-digit',
                          timeZone: 'UTC'
                        })
                      }</strong>
                    </span>
                  </div>
                  {config.server_time_utc && (
                    <div className="text-[9px] text-brand-text-muted/70 pl-3.5">
                      Server UTC: {new Date(config.server_time_utc).toISOString()}
                    </div>
                  )}
                  <div className="flex items-center gap-1.5 pt-1.5 border-t border-brand-border/40 mt-1 pl-3.5">
                    <span className="text-[10px] text-brand-text-muted">Status de hoje:</span>
                    {config.last_sent_date === config.server_time_br.split('T')[0] ? (
                      <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-emerald-50 text-emerald-700 border border-emerald-100 font-bold text-[9px] uppercase tracking-wide">
                        <Check size={10} /> Já disparada hoje ({config.last_sent_date})
                      </span>
                    ) : (
                      <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-amber-50 text-amber-700 border border-amber-100 font-bold text-[9px] uppercase tracking-wide">
                        <Clock size={10} /> Pendente / Não disparada hoje
                      </span>
                    )}
                  </div>
                </div>
              )}
            </div>

            <hr className="border-brand-border/40" />

            {/* Conteúdo da Notificação */}
            <div className="space-y-4">
              <h3 className="text-sm font-bold text-brand-text uppercase tracking-wider flex items-center gap-1.5 border-none p-0 pb-0">
                <AlignLeft size={16} className="text-brand-primary" />
                Conteúdo da Notificação
              </h3>

              {/* Título */}
              <div className="space-y-1">
                <label className="text-xs font-medium text-brand-text-muted">Título da Notificação</label>
                <input
                  type="text"
                  value={config.title}
                  onChange={e => setConfig({ ...config, title: e.target.value })}
                  placeholder="Ex: ⏰ Hora das Evoluções!"
                  className="input-field p-2.5"
                  maxLength={60}
                />
              </div>

              {/* Mensagem */}
              <div className="space-y-1">
                <label className="text-xs font-medium text-brand-text-muted">Mensagem / Corpo</label>
                <textarea
                  rows={3}
                  value={config.body}
                  onChange={e => setConfig({ ...config, body: e.target.value })}
                  placeholder="Ex: Não se esqueça de preencher as evoluções clínicas dos seus atendimentos de hoje..."
                  className="input-field p-2.5 text-sm"
                  maxLength={150}
                />
              </div>

              {/* Rota de Destino */}
              <div className="space-y-1">
                <label className="text-xs font-medium text-brand-text-muted flex items-center gap-1">
                  <LinkIcon size={12} />
                  URL de Destino
                </label>
                <input
                  type="text"
                  value={config.destination_url}
                  onChange={e => setConfig({ ...config, destination_url: e.target.value })}
                  placeholder="Ex: /painel/patients ou link completo"
                  className="input-field p-2.5"
                />
                <p className="text-[10px] text-brand-text-muted">Caminho interno do aplicativo que abrirá quando o profissional clicar na notificação.</p>
              </div>

              {/* Uploads e URLs de Mídia */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-1">
                {/* Ícone */}
                <div className="space-y-1.5">
                  <label className="text-xs font-medium text-brand-text-muted flex items-center gap-1">
                    <ImageIcon size={12} />
                    Ícone Personalizado (1:1)
                  </label>
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={config.icon_url}
                      onChange={e => setConfig({ ...config, icon_url: e.target.value })}
                      placeholder="Ex: https://.../icon.png"
                      className="input-field p-2 text-xs flex-1"
                    />
                    <label className="p-2.5 bg-brand-bg border border-brand-border rounded-xl hover:bg-brand-primary/5 cursor-pointer flex items-center justify-center text-brand-text-muted hover:text-brand-primary transition-colors flex-shrink-0">
                      {uploadingIcon ? <Loader2 size={16} className="animate-spin" /> : <Upload size={16} />}
                      <input 
                        type="file" 
                        accept="image/*" 
                        onChange={e => handleFileUpload(e, 'icon')} 
                        className="sr-only" 
                        disabled={uploadingIcon}
                      />
                    </label>
                  </div>
                  {config.icon_url && (
                    <div className="flex items-center gap-2 mt-1">
                      <img src={config.icon_url} alt="Ícone" className="w-8 h-8 rounded-lg object-cover border border-brand-border/40" />
                      <button 
                        type="button" 
                        onClick={() => setConfig({ ...config, icon_url: '' })}
                        className="text-[10px] text-red-500 hover:underline flex items-center gap-0.5 bg-transparent border-0 cursor-pointer"
                      >
                        <Trash2 size={10} /> Remover
                      </button>
                    </div>
                  )}
                </div>

                {/* Imagem de Capa */}
                <div className="space-y-1.5">
                  <label className="text-xs font-medium text-brand-text-muted flex items-center gap-1">
                    <ImageIcon size={12} />
                    Imagem de Capa (Opcional - Grande)
                  </label>
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={config.image_url}
                      onChange={e => setConfig({ ...config, image_url: e.target.value })}
                      placeholder="Ex: https://.../banner.jpg"
                      className="input-field p-2 text-xs flex-1"
                    />
                    <label className="p-2.5 bg-brand-bg border border-brand-border rounded-xl hover:bg-brand-primary/5 cursor-pointer flex items-center justify-center text-brand-text-muted hover:text-brand-primary transition-colors flex-shrink-0">
                      {uploadingImage ? <Loader2 size={16} className="animate-spin" /> : <Upload size={16} />}
                      <input 
                        type="file" 
                        accept="image/*" 
                        onChange={e => handleFileUpload(e, 'image')} 
                        className="sr-only" 
                        disabled={uploadingImage}
                      />
                    </label>
                  </div>
                  {config.image_url && (
                    <div className="flex items-center gap-2 mt-1">
                      <img src={config.image_url} alt="Capa" className="w-12 h-8 rounded object-cover border border-brand-border/40" />
                      <button 
                        type="button" 
                        onClick={() => setConfig({ ...config, image_url: '' })}
                        className="text-[10px] text-red-500 hover:underline flex items-center gap-0.5 bg-transparent border-0 cursor-pointer"
                      >
                        <Trash2 size={10} /> Remover
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* Ações */}
            <div className="flex flex-col sm:flex-row justify-end gap-3 pt-4 border-t border-brand-border/50">
              <button
                type="button"
                onClick={handleTestPush}
                disabled={testing}
                className="flex items-center justify-center gap-2 px-4 py-2.5 border border-brand-primary/30 text-brand-primary hover:bg-brand-primary/5 rounded-xl font-semibold text-sm transition-all cursor-pointer disabled:opacity-50"
              >
                {testing ? <Loader2 size={16} className="animate-spin" /> : <Play size={16} />}
                <span>Enviar Teste no meu Dispositivo</span>
              </button>
              <button
                type="button"
                onClick={handleSave}
                disabled={saving}
                className="flex items-center justify-center gap-2 px-6 py-2.5 bg-brand-primary hover:bg-brand-primary-hover text-white rounded-xl font-bold text-sm shadow-sm transition-all cursor-pointer disabled:opacity-50"
              >
                {saving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                <span>Salvar Configuração</span>
              </button>
            </div>

          </div>

          {/* Histórico de Disparos */}
          <div className="card p-6 bg-white shadow-sm border border-brand-border/60 space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-bold text-brand-text uppercase tracking-wider flex items-center gap-1.5 border-none p-0 pb-0">
                <History size={16} className="text-brand-primary" />
                Histórico de Disparos (Últimas 7 execuções)
              </h3>
              <button
                type="button"
                onClick={fetchHistory}
                disabled={historyLoading}
                className="p-1.5 text-brand-text-muted hover:text-brand-primary hover:bg-brand-primary/5 rounded-lg border border-transparent hover:border-brand-border transition-all cursor-pointer disabled:opacity-50 flex items-center justify-center"
                title="Atualizar histórico"
              >
                <RefreshCw size={14} className={historyLoading ? 'animate-spin' : ''} />
              </button>
            </div>

            {historyLoading ? (
              <div className="py-8 flex items-center justify-center text-xs text-brand-text-muted">
                <Loader2 size={16} className="animate-spin mr-2" /> Carregando histórico...
              </div>
            ) : history.length === 0 ? (
              <div className="py-8 text-center text-xs text-brand-text-muted border border-dashed border-brand-border rounded-xl">
                Nenhuma notificação enviada recentemente.
              </div>
            ) : (
              <div className="space-y-3">
                {history.map((log) => {
                  if (!log) return null;
                  let formattedDate = 'Data desconhecida';
                  try {
                    if (log.sent_at) {
                      const date = new Date(log.sent_at);
                      if (!isNaN(date.getTime())) {
                        formattedDate = date.toLocaleString('pt-BR', {
                          day: '2-digit',
                          month: '2-digit',
                          year: 'numeric',
                          hour: '2-digit',
                          minute: '2-digit'
                        });
                      }
                    }
                  } catch (e) {
                    console.error("Erro ao formatar data do log:", e);
                  }

                  const status = log.status || 'error';
                  const recipientsCount = log.recipients_count || 0;
                  const errorMessage = log.error_message || '';
                  const payload = log.payload || {};

                  return (
                    <div 
                      key={log.id || Math.random().toString()} 
                      className={`p-3.5 rounded-xl border text-xs transition-all ${
                        status === 'success' 
                          ? 'bg-emerald-50/20 border-emerald-100/50 hover:bg-emerald-50/30' 
                          : 'bg-red-50/20 border-red-100/50 hover:bg-red-50/30'
                      }`}
                    >
                      <div className="flex justify-between items-start">
                        <div className="w-full">
                          <div className="flex items-center gap-2">
                            <span className={`px-2 py-0.5 rounded-full font-bold text-[10px] tracking-wide uppercase ${
                              status === 'success' 
                                ? 'bg-emerald-100 text-emerald-800' 
                                : 'bg-red-100 text-red-805'
                            }`}>
                              {status === 'success' ? 'Sucesso' : 'Falha'}
                            </span>
                            <span className="font-semibold text-brand-text-muted">{formattedDate}</span>
                          </div>

                          {status === 'success' ? (
                            <p className="text-brand-text font-medium mt-2">
                              Enviada com sucesso para <strong className="text-brand-primary">{recipientsCount}</strong> profissionais ativos.
                            </p>
                          ) : (
                            <div className="mt-2 space-y-1">
                              <p className="text-red-800 font-bold">Erro no processamento do disparo:</p>
                              <p className="text-red-750 bg-red-100/10 p-2 rounded-lg font-mono text-[10px] select-all border border-red-100 leading-normal whitespace-pre-wrap">
                                {errorMessage || 'Erro desconhecido.'}
                              </p>
                            </div>
                          )}

                          {payload && payload.title && (
                            <div className="mt-2 text-stone-500 bg-stone-50 p-2 rounded-lg leading-relaxed border border-stone-100">
                              <span className="font-bold text-[10px] text-stone-400 block mb-0.5 uppercase tracking-wider">Conteúdo enviado:</span>
                              <strong>{payload.title}</strong> - {payload.body || ''}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>

        {/* Coluna Preview Mobile (Right) */}
        <div className="lg:col-span-5 flex flex-col items-center">
          <div className="sticky top-6 w-full max-w-[340px] space-y-3">
            <p className="text-xs font-bold text-brand-text-muted uppercase tracking-wider text-center flex items-center justify-center gap-1">
              <Smartphone size={14} className="text-brand-primary" />
              Visualização no Dispositivo
            </p>

            {/* Smartphone Mockup */}
            <div className="relative w-full h-[580px] bg-stone-900 rounded-[40px] p-3 shadow-2xl border-4 border-stone-850 overflow-hidden flex flex-col justify-start">

              {/* Speaker / Camera Notch */}
              <div className="absolute top-4 left-1/2 -translate-x-1/2 w-28 h-4 bg-stone-950 rounded-full z-20 flex items-center justify-between px-3">
                <div className="w-1.5 h-1.5 rounded-full bg-stone-800"></div>
                <div className="w-8 h-1 bg-stone-800 rounded-full"></div>
                <div className="w-1.5 h-1.5 rounded-full bg-stone-800"></div>
              </div>

              {/* Wallpaper / Background */}
              <div className="absolute inset-0 bg-gradient-to-tr from-brand-primary/80 via-purple-900 to-indigo-950 z-0"></div>

              {/* Status Bar */}
              <div className="relative z-10 flex justify-between items-center text-[10px] text-white px-5 pt-2 select-none opacity-80">
                <span className="font-semibold">{config.time || '08:00'}</span>
                <div className="flex items-center gap-1">
                  <span>📶</span>
                  <span>🔋</span>
                </div>
              </div>

              {/* Push Notification Card (Animated/Mockup) */}
              <div className="relative z-10 mt-6 mx-2 bg-white/90 backdrop-blur-md rounded-2xl p-3 shadow-lg border border-white/20 select-none animate-in slide-in-from-top-6 duration-300">
                <div className="flex gap-2.5 items-start">

                  {/* Icon */}
                  <div className="w-9 h-9 rounded-lg bg-brand-primary/10 flex-shrink-0 flex items-center justify-center overflow-hidden border border-brand-primary/10">
                    {displayIconUrl ? (
                      <img src={displayIconUrl} alt="Ícone notif" className="w-full h-full object-cover" />
                    ) : (
                      <Bell size={18} className="text-brand-primary" />
                    )}
                  </div>

                  {/* Text Content */}
                  <div className="flex-1 min-w-0">
                    <div className="flex justify-between items-center">
                      <p className="text-xs font-bold text-stone-900 truncate">
                        {config.title || 'Hora das Evoluções!'}
                      </p>
                      <span className="text-[9px] text-stone-500">agora</span>
                    </div>
                    <p className="text-[11px] text-stone-700 leading-normal mt-0.5 break-words">
                      {config.body || 'Não se esqueça de registrar as evoluções clínicas hoje.'}
                    </p>
                  </div>
                </div>

                {/* Big Capa Image */}
                {config.image_url && (
                  <div className="mt-2.5 rounded-lg overflow-hidden border border-stone-200/50 bg-stone-100 max-h-[120px] flex items-center justify-center">
                    <img src={config.image_url} alt="Capa notif" className="w-full h-full object-cover" />
                  </div>
                )}

                {/* Action button */}
                <div className="mt-2.5 pt-2 border-t border-stone-200/40 flex justify-between items-center text-[10px] text-brand-primary font-bold">
                  <span>Ver Detalhes</span>
                  <ChevronRight size={12} />
                </div>
              </div>

              {/* Screen Mockup Bottom Decorator (Indicator Bar) */}
              <div className="absolute bottom-2.5 left-1/2 -translate-x-1/2 w-32 h-1 bg-white/60 rounded-full z-10"></div>
            </div>

            {/* Dica de Instalação / Uso */}
            <div className="p-3.5 bg-brand-primary/5 rounded-xl border border-brand-primary/10 text-xs text-brand-text-muted leading-relaxed">
              💡 <strong>Instruções do Sistema:</strong> Este lembrete é enviado para todos os navegadores e celulares (Android/PWA) que aceitaram receber notificações. O tempo de entrega real pode variar ligeiramente de acordo com a fila de processamento do Google/Apple Push Service.
            </div>
          </div>
        </div>

      </div>
    </div>
  );
}

