import React, { useState, useEffect, useRef } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { supabase } from '../../supabaseClient';
import { showAlert, showConfirm, showPrompt } from '../../store/modalStore';
import { marked } from 'marked';
import DOMPurify from 'dompurify';
import { 
  Plus, Edit, Eye, Trash2, Copy, Check, Upload, Calendar, Clock, 
  BarChart3, List, MoveUp, MoveDown, ArrowLeft, ExternalLink, 
  RefreshCw, FileText, Info, AlertTriangle, AlertCircle, Sparkles, 
  CheckCircle2, X, MessageSquare, ChevronRight, Settings, Image as ImageIcon,
  Layout as LayoutIcon, Timer
} from 'lucide-react';

interface Journey {
  id: string;
  title: string;
  slug: string;
  subtitle: string | null;
  description: string | null;
  cover_image_url: string | null;
  total_days: number;
  status: 'draft' | 'active' | 'completed' | 'archived';
  start_date: string | null;
  end_date: string | null;
  timezone: string;
  public_url: string | null;
  whatsapp_main_group_url: string | null;
  whatsapp_support_group_url: string | null;
  show_whatsapp_main_group: boolean;
  show_scheduled_as_coming_soon: boolean;
  trial_url: string | null;
  website_url: string | null;
  seo_title: string | null;
  seo_description: string | null;
  created_at: string;
  updated_at: string;
}

interface JourneyContent {
  id: string;
  journey_id: string;
  day_number: number;
  title: string;
  slug: string;
  short_description: string | null;
  content: string | null;
  image_url: string | null;
  image_alt: string | null;
  video_url: string | null;
  video_embed_url: string | null;
  content_type: 'text' | 'image' | 'video' | 'mixed';
  cta_text: string | null;
  cta_url: string | null;
  secondary_cta_text: string | null;
  secondary_cta_url: string | null;
  whatsapp_message: string | null;
  image_prompt: string | null;
  publication_status: 'draft' | 'scheduled' | 'published' | 'archived';
  publication_date: string | null;
  publication_time: string | null;
  published_at: string | null;
  sort_order: number;
  allow_indexing: boolean;
  created_at: string;
  updated_at: string;
}

type ViewMode = 'list_journeys' | 'edit_journey' | 'list_contents' | 'edit_content' | 'whatsapp_fixed';
interface JourneyWhatsAppPublication {
  id: string; journey_content_id: string; destination_key: string; scheduled_at: string; status: string;
  attempts: number; published_at: string | null; last_error_code: string | null; last_error_message: string | null;
  journey_contents?: { day_number: number; title: string; publication_status: string; publication_date: string | null; publication_time: string | null };
}

interface JourneyPublicationCronStatus {
  jobName: string;
  schedule: string;
  active: boolean;
  nextRunAt: string | null;
  lastRun: { status: string; startTime: string; endTime: string | null; returnMessage: string | null } | null;
}

export default function JourneyAdmin() {
  const navigate = useNavigate();
  const location = useLocation();
  const [viewMode, setViewMode] = useState<ViewMode>('list_journeys');

  // Lista de jornadas
  const [journeys, setJourneys] = useState<Journey[]>([]);
  const [loadingJourneys, setLoadingJourneys] = useState(true);
  const [journeyCounts, setJourneyCounts] = useState<Record<string, { published: number; scheduled: number }>>({});

  // Seleções
  const [selectedJourney, setSelectedJourney] = useState<Journey | null>(null);
  const [selectedContent, setSelectedContent] = useState<JourneyContent | null>(null);

  // Lista de conteúdos
  const [contents, setContents] = useState<JourneyContent[]>([]);
  const [loadingContents, setLoadingContents] = useState(false);
  const [journeyPublications, setJourneyPublications] = useState<JourneyWhatsAppPublication[]>([]);
  const [journeyCronStatus, setJourneyCronStatus] = useState<JourneyPublicationCronStatus | null>(null);
  const [loadingJourneyCronStatus, setLoadingJourneyCronStatus] = useState(false);
  const [journeyCronStatusError, setJourneyCronStatusError] = useState<string | null>(null);

  // Feedbacks visuais
  const [saving, setSaving] = useState(false);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  // Estado formulário Journey
  const [journeyForm, setJourneyForm] = useState<Partial<Journey>>({
    title: '',
    subtitle: '',
    description: '',
    slug: '',
    cover_image_url: '',
    total_days: 15,
    status: 'draft',
    start_date: '',
    end_date: '',
    timezone: 'America/Sao_Paulo',
    whatsapp_main_group_url: '',
    whatsapp_support_group_url: '',
    show_whatsapp_main_group: false,
    show_scheduled_as_coming_soon: true,
    trial_url: '',
    website_url: '',
    seo_title: '',
    seo_description: '',
  });

  // Estado formulário Content
  const [contentForm, setContentForm] = useState<Partial<JourneyContent>>({
    day_number: 1,
    title: '',
    slug: '',
    short_description: '',
    content: '',
    image_url: '',
    image_alt: '',
    video_url: '',
    video_embed_url: '',
    content_type: 'text',
    cta_text: '',
    cta_url: '',
    secondary_cta_text: '',
    secondary_cta_url: '',
    whatsapp_message: '',
    image_prompt: '',
    publication_status: 'draft',
    publication_date: '',
    publication_time: '08:00',
    allow_indexing: true,
  });

  // Preview de Markdown
  const [markdownPreview, setMarkdownPreview] = useState('');

  // Uploads
  const [uploadingImage, setUploadingImage] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sincroniza estado com a URL em caso de navegação direta ou troca de rota
  useEffect(() => {
    syncStateWithUrl(location.pathname);
  }, [location.pathname]);

  useEffect(() => {
    if (contentForm.content) {
      const html = marked.parse(contentForm.content, { breaks: true }) as string;
      setMarkdownPreview(DOMPurify.sanitize(html));
    } else {
      setMarkdownPreview('');
    }
  }, [contentForm.content]);

  // Função para sincronizar a rota do navegador com o estado local do painel
  const syncStateWithUrl = async (path: string) => {
    const parts = path.split('/').filter(Boolean); // ex: ['admin', 'jornada', ...]

    // Garante que a listagem de jornadas esteja carregada
    let currentJourneys = journeys;
    if (currentJourneys.length === 0) {
      currentJourneys = await fetchJourneys();
    }

    // Casos de rotas:
    // 1. Listar jornadas: /admin/jornada
    if (parts.length === 2 && parts[1] === 'jornada') {
      setViewMode('list_journeys');
      setSelectedJourney(null);
      setSelectedContent(null);
      return;
    }

    // 2. Nova jornada: /admin/jornada/novo
    if (parts.length === 3 && parts[1] === 'jornada' && parts[2] === 'novo') {
      setViewMode('edit_journey');
      setSelectedJourney(null);
      setJourneyForm({
        title: '',
        subtitle: '',
        description: '',
        slug: '',
        cover_image_url: '',
        total_days: 15,
        status: 'draft',
        start_date: '',
        end_date: '',
        timezone: 'America/Sao_Paulo',
        whatsapp_main_group_url: '',
        whatsapp_support_group_url: '',
        show_whatsapp_main_group: false,
        show_scheduled_as_coming_soon: true,
        trial_url: '',
        website_url: '',
        seo_title: '',
        seo_description: '',
      });
      return;
    }

    // 3. Editar jornada: /admin/jornada/editar/:journeySlug
    if (parts.length === 4 && parts[1] === 'jornada' && parts[2] === 'editar') {
      const slug = parts[3];
      const foundJourney = currentJourneys.find(j => j.slug === slug);
      if (foundJourney) {
        setSelectedJourney(foundJourney);
        setJourneyForm({ ...foundJourney });
        setViewMode('edit_journey');
      } else {
        navigate('/admin/jornada');
      }
      return;
    }

    // 4. WhatsApp fixado: /admin/jornada/:journeySlug/conteudos/whatsapp-fixado
    if (parts.length === 5 && parts[1] === 'jornada' && parts[3] === 'conteudos' && parts[4] === 'whatsapp-fixado') {
      const jSlug = parts[2];
      const foundJourney = currentJourneys.find(j => j.slug === jSlug);
      if (foundJourney) {
        setSelectedJourney(foundJourney);
        setViewMode('whatsapp_fixed');
        await fetchContents(foundJourney.id);
      } else {
        navigate('/admin/jornada');
      }
      return;
    }

    // 5. Novo conteúdo: /admin/jornada/:journeySlug/conteudos/novo
    if (parts.length === 5 && parts[1] === 'jornada' && parts[3] === 'conteudos' && parts[4] === 'novo') {
      const jSlug = parts[2];
      const foundJourney = currentJourneys.find(j => j.slug === jSlug);
      if (foundJourney) {
        setSelectedJourney(foundJourney);

        let currentContents = contents;
        if (currentContents.length === 0 || currentContents[0]?.journey_id !== foundJourney.id) {
          const { data: contentData, error } = await supabase
            .from('journey_contents')
            .select('*')
            .eq('journey_id', foundJourney.id)
            .order('day_number', { ascending: true });
          if (!error && contentData) {
            setContents(contentData);
            currentContents = contentData;
          }
        }

        const nextDay = currentContents.length > 0 ? Math.max(...currentContents.map(c => c.day_number)) + 1 : 1;
        setSelectedContent(null);
        setContentForm({
          day_number: nextDay <= foundJourney.total_days ? nextDay : 1,
          title: '',
          slug: '',
          short_description: '',
          content: '',
          image_url: '',
          image_alt: '',
          video_url: '',
          video_embed_url: '',
          content_type: 'text',
          cta_text: '',
          cta_url: '',
          secondary_cta_text: '',
          secondary_cta_url: '',
          whatsapp_message: '',
          image_prompt: '',
          publication_status: 'draft',
          publication_date: new Date().toISOString().split('T')[0],
          publication_time: '08:00',
          allow_indexing: true,
        });
        setViewMode('edit_content');
      } else {
        navigate('/admin/jornada');
      }
      return;
    }

    // 6. Listar conteúdos: /admin/jornada/:journeySlug/conteudos
    if (parts.length === 4 && parts[1] === 'jornada' && parts[3] === 'conteudos') {
      const jSlug = parts[2];
      const foundJourney = currentJourneys.find(j => j.slug === jSlug);
      if (foundJourney) {
        setSelectedJourney(foundJourney);
        setViewMode('list_contents');
        await fetchContents(foundJourney.id);
        await fetchJourneyPublications(foundJourney.id);
        await fetchJourneyPublicationCronStatus();
      } else {
        navigate('/admin/jornada');
      }
      return;
    }

    // 7. Editar conteúdo: /admin/jornada/:journeySlug/conteudos/:contentSlug
    if (parts.length === 5 && parts[1] === 'jornada' && parts[3] === 'conteudos') {
      const jSlug = parts[2];
      const cSlug = parts[4];
      const foundJourney = currentJourneys.find(j => j.slug === jSlug);
      if (foundJourney) {
        setSelectedJourney(foundJourney);

        let currentContents = contents;
        if (currentContents.length === 0 || currentContents[0]?.journey_id !== foundJourney.id) {
          const { data: contentData, error } = await supabase
            .from('journey_contents')
            .select('*')
            .eq('journey_id', foundJourney.id)
            .order('day_number', { ascending: true });
          if (!error && contentData) {
            setContents(contentData);
            currentContents = contentData;
          }
        }

        const foundContent = currentContents.find(c => c.slug === cSlug);
        if (foundContent) {
          setSelectedContent(foundContent);
          setContentForm({ ...foundContent });
          setViewMode('edit_content');
        } else {
          navigate(`/admin/jornada/${foundJourney.slug}/conteudos`);
        }
      } else {
        navigate('/admin/jornada');
      }
      return;
    }
  };

  // Carrega lista de jornadas
  const fetchJourneys = async () => {
    setLoadingJourneys(true);
    try {
      const { data, error } = await supabase
        .from('journeys')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      const loadedJourneys = data || [];
      setJourneys(loadedJourneys);

      // Busca contagens de conteúdos para cada jornada
      const counts: Record<string, { published: number; scheduled: number }> = {};
      for (const j of loadedJourneys) {
        const { data: contentData, error: cntError } = await supabase
          .from('journey_contents')
          .select('publication_status')
          .eq('journey_id', j.id);

        if (!cntError && contentData) {
          counts[j.id] = {
            published: contentData.filter(c => c.publication_status === 'published').length,
            scheduled: contentData.filter(c => c.publication_status === 'scheduled').length,
          };
        }
      }
      setJourneyCounts(counts);
      return loadedJourneys;
    } catch (err) {
      console.error('Erro ao buscar jornadas:', err);
      return [];
    } finally {
      setLoadingJourneys(false);
    }
  };

  // Carrega conteúdos da jornada selecionada
  const fetchContents = async (journeyId: string) => {
    setLoadingContents(true);
    try {
      const { data, error } = await supabase
        .from('journey_contents')
        .select('*')
        .eq('journey_id', journeyId)
        .order('day_number', { ascending: true });

      if (error) throw error;
      setContents(data || []);
    } catch (err) {
      console.error('Erro ao buscar conteúdos da jornada:', err);
    } finally {
      setLoadingContents(false);
    }
  };

  const fetchJourneyPublications = async (journeyId: string) => {
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const response = await fetch(`/api/admin/journey-whatsapp-publications?journeyId=${encodeURIComponent(journeyId)}`, {
        headers: { Authorization: `Bearer ${sessionData.session?.access_token || ''}` }, cache: 'no-store'
      });
      const body = await response.json();
      if (!response.ok) throw new Error(body.error || 'Não foi possível carregar a fila.');
      setJourneyPublications(body.publications || []);
    } catch (error) { console.error('Erro ao carregar publicações WhatsApp da jornada:', error); }
  };

  const fetchJourneyPublicationCronStatus = async () => {
    setLoadingJourneyCronStatus(true);
    setJourneyCronStatusError(null);
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const response = await fetch('/api/admin/journey-publication-cron', {
        headers: { Authorization: `Bearer ${sessionData.session?.access_token || ''}` }, cache: 'no-store'
      });
      const body = await response.json();
      if (!response.ok) throw new Error(body.error || 'Não foi possível carregar o cron.');
      setJourneyCronStatus(body);
    } catch (error: any) {
      setJourneyCronStatus(null);
      setJourneyCronStatusError(error?.message || 'Não foi possível carregar o cron.');
    } finally {
      setLoadingJourneyCronStatus(false);
    }
  };

  const formatCronDateTime = (value: string | null) => {
    if (!value) return '—';
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return '—';
    return new Intl.DateTimeFormat('pt-BR', {
      dateStyle: 'short', timeStyle: 'short', timeZone: 'America/Sao_Paulo'
    }).format(date);
  };

